css:
.coo-root *{margin:0;padding:0;box-sizing:border-box}
.coo-root{
  font-family:'Inter','Segoe UI',system-ui,sans-serif;
  background:#F3FAF4;color:#152418;font-size:14px;line-height:1.45;
  border-radius:14px;overflow:hidden;
}
.coo-root button{font-family:inherit;cursor:pointer}
.coo-root .num{font-variant-numeric:tabular-nums}
 .navbar{
     display:none;

 }
 .web-footer{
     display:none;
 }
/* header */
.coo-root .hdr{background:linear-gradient(135deg,#0F3D1E,#1B5E20 70%,#2E7D32);color:#fff}
.coo-root .hdr-in{padding:14px 20px;display:flex;align-items:center;gap:16px;flex-wrap:wrap}
.coo-root .logo{display:flex;align-items:center;gap:12px}
.coo-root .logo-mark{width:40px;height:40px;border-radius:11px;background:#fff;color:#1B5E20;
  display:flex;align-items:center;justify-content:center;font-weight:800;font-size:19px}
.coo-root .logo h1{font-size:16px;font-weight:700;line-height:1.15;color:#FFFFFF !important;}
.coo-root .logo small{display:block;font-size:10px;letter-spacing:2px;text-transform:uppercase;color:#BFE3C4}
.coo-root .hdr-mid{flex:1;display:flex;align-items:center;gap:10px;justify-content:center;flex-wrap:wrap}
.coo-root .live-chip,.coo-root .br-filter,.coo-root .cyc-chip{
  display:flex;align-items:center;gap:8px;background:rgba(255,255,255,.12);
  border:1px solid rgba(255,255,255,.22);padding:7px 14px;border-radius:99px;font-size:12px;font-weight:600}
.coo-root .pulse{width:8px;height:8px;border-radius:50%;background:#7CF29A;animation:coopl 2s infinite}
@keyframes coopl{0%{box-shadow:0 0 0 0 rgba(124,242,154,.65)}70%{box-shadow:0 0 0 9px rgba(124,242,154,0)}100%{box-shadow:0 0 0 0 rgba(124,242,154,0)}}
@media (prefers-reduced-motion:reduce){.coo-root .pulse{animation:none}}
.coo-root .br-filter{padding:4px 8px 4px 14px}
.coo-root .br-filter select{background:transparent;border:0;color:#fff;font-size:12px;font-weight:600;
  outline:none;padding:4px 6px;cursor:pointer}
.coo-root .br-filter select option{color:#152418}
.coo-root .hdr-end{display:flex;align-items:center;gap:12px}
.coo-root .btn-refresh{background:rgba(255,255,255,.16);border:1px solid rgba(255,255,255,.3);
  color:#fff;padding:7px 14px;border-radius:99px;font-size:12px;font-weight:600}
.coo-root .btn-refresh:hover{background:rgba(255,255,255,.28)}
.coo-root .clk{text-align:right;line-height:1.2}
.coo-root .clk b{font-size:15px;font-variant-numeric:tabular-nums}
.coo-root .clk span{display:block;font-size:10px;color:#BFE3C4}

/* section eyebrow */
.coo-root .sec-eyebrow{font-size:11px;font-weight:700;letter-spacing:2px;text-transform:uppercase;
  color:#2E7D32;margin:22px 0 12px;display:flex;align-items:center;gap:12px}
.coo-root .sec-eyebrow::after{content:"";flex:1;height:1px;background:#DCE9DE}
.coo-root .sec-eyebrow:first-of-type{margin-top:4px}
.coo-root .br-lb{font-size:11px;color:#BFE3C4;font-weight:600}
.coo-root .ftr{text-align:center;padding:20px;font-size:11px;color:#5F6F63;
  border-top:1px solid #DCE9DE;background:#fff}

/* strip */
.coo-root .wrap{padding:18px 20px 24px}
.coo-root .strip{display:flex;gap:10px;overflow-x:auto;padding-bottom:12px;margin-bottom:14px}
.coo-root .sp{flex:0 0 auto;background:#fff;border:1px solid #DCE9DE;border-radius:12px;
  padding:9px 14px;display:flex;flex-direction:column;gap:2px;min-width:118px}
.coo-root .sp b{font-size:15px;font-weight:700;font-variant-numeric:tabular-nums}
.coo-root .sp span{font-size:10px;color:#5F6F63;text-transform:uppercase;letter-spacing:.6px}

/* tiles */
.coo-root .grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(264px,1fr));gap:14px}
.coo-root .tile{background:#fff;border:1px solid #DCE9DE;border-radius:14px;padding:16px;
  cursor:pointer;transition:transform .16s,box-shadow .16s;
  box-shadow:0 1px 2px rgba(15,61,30,.06),0 4px 14px rgba(15,61,30,.07);min-height:150px}
.coo-root .tile:hover{transform:translateY(-2px);box-shadow:0 6px 24px rgba(15,61,30,.16)}
.coo-root .tile:focus-visible{outline:2px solid #2E7D32;outline-offset:2px}
.coo-root .t-hd{display:flex;align-items:center;gap:9px;margin-bottom:12px}
.coo-root .t-ico{width:30px;height:30px;border-radius:9px;background:#E8F5E9;color:#1B5E20;
  display:flex;align-items:center;justify-content:center;font-size:14px;flex:0 0 auto}
.coo-root .t-nm{font-size:12.5px;font-weight:700;letter-spacing:.2px;flex:1}
.coo-root .t-big{font-size:26px;font-weight:800;letter-spacing:-.5px;font-variant-numeric:tabular-nums}
.coo-root .t-sub{font-size:11.5px;color:#5F6F63;margin-top:2px}
.coo-root .t-stats{display:flex;gap:14px;margin-top:12px;padding-top:11px;border-top:1px dashed #DCE9DE}
.coo-root .t-st{display:flex;flex-direction:column}
.coo-root .t-st b{font-size:13px;font-weight:700;font-variant-numeric:tabular-nums}
.coo-root .t-st span{font-size:9.5px;color:#5F6F63;text-transform:uppercase;letter-spacing:.5px}
.coo-root .badge{background:#C62828;color:#fff;font-size:10px;font-weight:700;
  padding:2px 7px;border-radius:99px}

/* bars */
.coo-root .hbar{height:6px;background:#E8F5E9;border-radius:99px;overflow:hidden;margin-top:8px}
.coo-root .hbar i{display:block;height:100%;background:#43A047;border-radius:99px}
.coo-root .hbar i.r{background:#C62828}
.coo-root .hbar i.a{background:#E65100}

/* pills */
.coo-root .pill{font-size:9.5px;font-weight:700;padding:2px 8px;border-radius:99px;
  text-transform:uppercase;letter-spacing:.4px;white-space:nowrap}
.coo-root .p-g{background:#E8F5E9;color:#1B5E20}
.coo-root .p-r{background:#FDECEA;color:#C62828}
.coo-root .p-a{background:#FFF3E0;color:#E65100}
.coo-root .p-b{background:#E3F2FD;color:#1565C0}
.coo-root .p-gr{background:#EFF2F0;color:#5F6F63}

/* modal */
.coo-root .ovl{position:fixed;inset:0;background:rgba(15,32,20,.55);z-index:2000;
  display:none;justify-content:flex-end}
.coo-root .ovl.on{display:flex}
.coo-root .modal{background:#F3FAF4;width:100%;max-width:760px;height:100%;
  display:flex;flex-direction:column;overflow:hidden;box-shadow:-8px 0 32px rgba(15,61,30,.28);
  transform:translateX(100%);animation:cooSlide .28s ease forwards}
@keyframes cooSlide{to{transform:translateX(0)}}
@media (prefers-reduced-motion:reduce){.coo-root .modal{animation:none;transform:none}}
@media(max-width:600px){.coo-root .modal{max-width:100%}}
.coo-root .m-hd{display:flex;align-items:center;gap:12px;padding:16px 18px;
  background:linear-gradient(135deg,#0F3D1E,#2E7D32);color:#fff}
.coo-root .m-ico{width:36px;height:36px;border-radius:10px;background:rgba(255,255,255,.16);
  display:flex;align-items:center;justify-content:center}
.coo-root .m-ttl{flex:1}
.coo-root .m-ttl h3{font-size:15px;font-weight:700}
.coo-root .m-ttl span{font-size:11px;color:#BFE3C4}
.coo-root .m-x{background:rgba(255,255,255,.16);border:0;color:#fff;width:30px;height:30px;
  border-radius:8px;font-size:14px}
.coo-root .m-x:hover{background:rgba(255,255,255,.3)}
.coo-root .m-back{background:rgba(255,255,255,.16);border:0;color:#fff;width:30px;height:30px;
  border-radius:8px;font-size:15px;flex:0 0 auto}
.coo-root .m-back:hover{background:rgba(255,255,255,.3)}
.coo-root .m-back[hidden]{display:none}

/* drill-down rows */
.coo-root tr.drill{cursor:pointer}
.coo-root tr.drill:hover{background:#E8F5E9}
.coo-root tr.drill:focus-visible{outline:2px solid #2E7D32;outline-offset:-2px}
.coo-root tr.drill td:last-child::after{content:"\203A";color:#5F6F63;
  float:right;font-weight:700;padding-left:8px}
.coo-root .crumb{display:flex;gap:6px;align-items:center;flex-wrap:wrap;
  font-size:10.5px;color:#5F6F63;margin-bottom:10px}
.coo-root .crumb b{color:#1B5E20}

/* detail panel */
.coo-root .dl{display:grid;grid-template-columns:repeat(auto-fit,minmax(190px,1fr));
  gap:10px;background:#fff;border:1px solid #DCE9DE;border-radius:10px;padding:14px;margin-bottom:14px}
.coo-root .dl div{display:flex;flex-direction:column;gap:2px;min-width:0}
.coo-root .dl span{font-size:9.5px;color:#5F6F63;text-transform:uppercase;letter-spacing:.5px}
.coo-root .dl b{font-size:13px;font-weight:700;word-break:break-word}
.coo-root .note{background:#fff;border:1px solid #DCE9DE;border-left:3px solid #43A047;
  border-radius:8px;padding:12px;font-size:12px;margin-bottom:14px;white-space:pre-wrap;
  word-break:break-word}
.coo-root .sec-h{font-size:11px;text-transform:uppercase;letter-spacing:.6px;
  color:#5F6F63;margin:16px 0 8px;font-weight:700}
.coo-root .lnk{background:#E8F5E9;border:1px solid #C8E6C9;color:#1B5E20;
  padding:6px 12px;border-radius:8px;font-size:11.5px;font-weight:700;text-decoration:none;
  display:inline-block;margin-top:4px}
.coo-root .lnk:hover{background:#C8E6C9}
.coo-root .go-lnk{background:#1B5E20;color:#fff;padding:4px 10px;border-radius:6px;
  font-size:10.5px;font-weight:700;text-decoration:none;white-space:nowrap;display:inline-block}
.coo-root .go-lnk:hover{background:#2E7D32}
.coo-root tr[data-open-doctype] td:last-child::after{content:""}
.coo-root .m-kpis{display:flex;gap:10px;padding:14px 18px;background:#fff;
  border-bottom:1px solid #DCE9DE;overflow-x:auto}
.coo-root .m-kpi{flex:0 0 auto;display:flex;flex-direction:column;min-width:96px}
.coo-root .m-kpi b{font-size:17px;font-weight:800;font-variant-numeric:tabular-nums}
.coo-root .m-kpi span{font-size:9.5px;color:#5F6F63;text-transform:uppercase;letter-spacing:.5px}
.coo-root .m-kpi b.r{color:#C62828}
.coo-root .m-kpi b.a{color:#E65100}
.coo-root .m-kpi b.g{color:#2E7D32}
.coo-root .m-body{padding:16px 18px;overflow-y:auto;flex:1}

/* table */
.coo-root table{width:100%;border-collapse:collapse;background:#fff;
  border:1px solid #DCE9DE;border-radius:10px;overflow:hidden}
.coo-root th{background:#E8F5E9;color:#0F3D1E;font-size:10px;font-weight:700;
  text-transform:uppercase;letter-spacing:.6px;padding:9px 10px;text-align:left;white-space:nowrap}
.coo-root td{padding:9px 10px;font-size:12px;border-top:1px solid #EDF4EE;vertical-align:middle}
.coo-root tbody tr:hover{background:#F3FAF4}
.coo-root td.rt{text-align:right;font-variant-numeric:tabular-nums}
.coo-root th.rt{text-align:right}
.coo-root .wn{font-weight:700;font-size:12px}
.coo-root .wm{font-size:10px;color:#5F6F63}

/* states */
.coo-root .empty,.coo-root .err{padding:22px;text-align:center;font-size:12.5px;
  border-radius:10px;border:1px dashed #DCE9DE;background:#fff;color:#5F6F63}
.coo-root .err{border-color:#F3C9C4;background:#FDECEA;color:#C62828}
.coo-root .sk{background:linear-gradient(90deg,#EDF4EE 25%,#E2EEE4 50%,#EDF4EE 75%);
  background-size:200% 100%;animation:coosk 1.3s infinite;border-radius:6px;color:transparent}
@keyframes coosk{0%{background-position:200% 0}100%{background-position:-200% 0}}
@media (prefers-reduced-motion:reduce){.coo-root .sk{animation:none}}

/* toast */
.coo-root .toast{position:fixed;bottom:22px;left:50%;transform:translateX(-50%) translateY(80px);
  background:#0F3D1E;color:#fff;padding:11px 20px;border-radius:99px;font-size:12.5px;
  font-weight:600;z-index:2200;opacity:0;transition:all .25s;pointer-events:none}
.coo-root .toast.on{transform:translateX(-50%) translateY(0);opacity:1}

@media(max-width:640px){
  .coo-root .grid{grid-template-columns:1fr}
  .coo-root .hdr-mid{justify-content:flex-start}
  .coo-root .m-body{padding:12px}
}



/* modal footer */
.coo-root .m-ft{display:flex;align-items:center;justify-content:space-between;gap:12px;
  padding:12px 18px;background:#fff;border-top:1px solid #DCE9DE;flex-wrap:wrap}
.coo-root .m-note{font-size:11px;color:#5F6F63}
.coo-root .btn-go{background:#1B5E20;color:#fff;border:0;padding:9px 16px;border-radius:9px;
  font-size:12px;font-weight:700}
.coo-root .btn-go:hover{background:#2E7D32}
.coo-root .btn-go[hidden]{display:none}

/* LEVEL 3 full page */
.coo-root .full{position:fixed;inset:0;background:#F3FAF4;z-index:2100;display:none;
  flex-direction:column}
.coo-root .full.on{display:flex}
.coo-root .f-hd{display:flex;align-items:center;gap:14px;padding:16px 22px;
  background:linear-gradient(135deg,#0F3D1E,#1B5E20 70%,#2E7D32);color:#fff}
.coo-root .f-back{background:rgba(255,255,255,.16);border:0;color:#fff;width:34px;height:34px;
  border-radius:9px;font-size:16px;flex:0 0 auto}
.coo-root .f-back:hover{background:rgba(255,255,255,.3)}
.coo-root .f-bc{font-size:10px;letter-spacing:1.6px;text-transform:uppercase;color:#BFE3C4}
.coo-root .f-hd h2{font-size:18px;font-weight:700}
.coo-root .f-hd .m-x{margin-left:auto}
.coo-root .f-bd{flex:1;overflow-y:auto;padding:20px 22px 40px}
.coo-root .f-kpis{display:grid;grid-template-columns:repeat(auto-fit,minmax(140px,1fr));
  gap:12px;margin-bottom:18px}
.coo-root .f-kpi{background:#fff;border:1px solid #DCE9DE;border-radius:12px;padding:14px;
  display:flex;flex-direction:column;gap:3px;box-shadow:0 1px 2px rgba(15,61,30,.05)}
.coo-root .f-kpi b{font-size:21px;font-weight:800;font-variant-numeric:tabular-nums}
.coo-root .f-kpi span{font-size:10px;color:#5F6F63;text-transform:uppercase;letter-spacing:.6px}
.coo-root .f-kpi b.r{color:#C62828}
.coo-root .f-kpi b.a{color:#E65100}
.coo-root .f-kpi b.g{color:#2E7D32}
.coo-root .f-kpi b.bl{color:#1565C0}
.coo-root .f-card{background:#fff;border:1px solid #DCE9DE;border-radius:12px;padding:16px;
  margin-bottom:16px;box-shadow:0 1px 2px rgba(15,61,30,.05)}
.coo-root .f-card h3{font-size:12px;font-weight:700;text-transform:uppercase;letter-spacing:1px;
  color:#0F3D1E;margin-bottom:12px}
.coo-root .f-2col{display:grid;grid-template-columns:1fr 1fr;gap:16px}
@media(max-width:840px){.coo-root .f-2col{grid-template-columns:1fr}}

/* bar chart */
.coo-root .bc{display:flex;flex-direction:column;gap:9px}
.coo-root .bc-row{display:grid;grid-template-columns:130px 1fr 78px;align-items:center;gap:10px}
.coo-root .bc-n{font-size:11.5px;font-weight:600;overflow:hidden;text-overflow:ellipsis;
  white-space:nowrap}
.coo-root .bc-t{height:20px;background:#E8F5E9;border-radius:6px;overflow:hidden}
.coo-root .bc-t i{display:block;height:100%;background:linear-gradient(90deg,#43A047,#1B5E20);
  border-radius:6px;transition:width .5s}
.coo-root .bc-v{font-size:11.5px;font-weight:700;text-align:right;font-variant-numeric:tabular-nums}
@media (prefers-reduced-motion:reduce){.coo-root .bc-t i{transition:none}}
@media(max-width:600px){.coo-root .bc-row{grid-template-columns:96px 1fr 66px}}


/* global From/To date range */
.coo-root .global-range{
  display:flex;align-items:flex-end;gap:7px;flex-wrap:wrap;
  background:rgba(255,255,255,.11);border:1px solid rgba(255,255,255,.22);
  border-radius:12px;padding:6px 8px
}
.coo-root .range-field{display:flex;flex-direction:column;gap:3px;min-width:118px}
.coo-root .range-field span{
  font-size:8.5px;line-height:1;text-transform:uppercase;letter-spacing:.65px;
  font-weight:700;color:#5F6F63
}
.coo-root .global-range .range-field span{color:#BFE3C4}
.coo-root .range-field input,
.coo-root .range-field select{
  width:100%;min-height:31px;border:1px solid #C8DCCB;border-radius:7px;
  padding:5px 8px;background:#fff;color:#152418;font-family:inherit;
  font-size:11px;font-weight:600;outline:none
}
.coo-root .range-field input:focus,
.coo-root .range-field select:focus{
  border-color:#43A047;box-shadow:0 0 0 2px rgba(67,160,71,.15)
}
.coo-root .global-range .range-preset-field{min-width:126px}
.coo-root .range-apply{
  min-height:31px;border:0;border-radius:8px;padding:6px 13px;
  background:#1B5E20;color:#fff;font-size:11px;font-weight:700;white-space:nowrap
}
.coo-root .global-range .range-apply{
  background:#fff;color:#1B5E20
}
.coo-root .range-apply:hover{filter:brightness(.96)}
.coo-root .range-apply:disabled{opacity:.6;cursor:wait}
.coo-root .range-panel{
  display:flex;align-items:flex-end;gap:10px;flex-wrap:wrap;
  background:#fff;border:1px solid #DCE9DE;border-radius:11px;
  padding:12px;margin-bottom:14px;box-shadow:0 1px 2px rgba(15,61,30,.04)
}
.coo-root .range-panel .range-field{min-width:145px}
.coo-root .range-panel .range-help{
  flex:1 1 220px;font-size:10.5px;line-height:1.35;color:#5F6F63;
  padding:0 2px 2px
}
.coo-root .t-range{
  display:inline-flex;align-items:center;align-self:flex-start;margin-top:2px;
  border:1px solid #DCE9DE;background:#F3FAF4;color:#2E7D32;
  border-radius:99px;padding:2px 8px;font-size:9px;font-weight:700;
  letter-spacing:.35px;white-space:nowrap
}

@media(max-width:1100px){
  .coo-root .hdr-mid{justify-content:flex-start}
  .coo-root .global-range{width:100%}
}
@media(max-width:700px){
  .coo-root .global-range{align-items:stretch}
  .coo-root .global-range .range-field{flex:1 1 135px}
  .coo-root .global-range .range-apply{flex:1 1 100%;width:100%}
  .coo-root .range-panel .range-field{flex:1 1 135px;min-width:0}
  .coo-root .range-panel .range-apply{flex:1 1 100%;width:100%}
}

/* FINAL HEADER TITLE OVERRIDE */
.coo-root .hdr .logo h1,
.coo-root .hdr h1 {
  color: #FFFFFF !important;
  opacity: 1 !important;
}

/* =========================================================
   COO POPUPS — WIDER + FILTER CONTROLS IN ONE LINE
   Added: 22-Jul-2026
   ========================================================= */

/* Make every Level-2 popup wider, while retaining the slide-in design. */
.coo-root .modal {
  width: min(96vw, 1120px) !important;
  max-width: 1120px !important;
}

/* Standard popup filters: From | To | Quick Range | Apply */
.coo-root .range-panel {
  display: grid !important;
  grid-template-columns: repeat(3, minmax(150px, 1fr)) max-content;
  align-items: end !important;
  gap: 10px !important;
  flex-wrap: unset !important;
}

/* Appointments and Service also contain a Branch selector. */
.coo-root .range-panel[data-range-tile="appointments"],
.coo-root .range-panel[data-range-tile="service"] {
  grid-template-columns: repeat(4, minmax(145px, 1fr)) max-content;
}

.coo-root .range-panel .range-field {
  width: 100%;
  min-width: 0 !important;
}

.coo-root .range-panel .range-apply {
  width: auto !important;
  min-width: 105px;
  min-height: 35px;
  align-self: end;
}

/* Keep the explanation below the controls instead of occupying their row. */
.coo-root .range-panel .range-help {
  grid-column: 1 / -1;
  width: 100%;
  padding-top: 2px;
}

/* Give wide tables more usable space inside the popup. */
.coo-root .m-body {
  padding: 18px 20px !important;
}

.coo-root .m-kpis {
  padding-left: 20px !important;
  padding-right: 20px !important;
}

/* Tablet: two controls per row. */
@media (max-width: 900px) {
  .coo-root .modal {
    width: 100% !important;
    max-width: 92vw !important;
  }

  .coo-root .range-panel,
  .coo-root .range-panel[data-range-tile="appointments"],
  .coo-root .range-panel[data-range-tile="service"] {
    grid-template-columns: repeat(2, minmax(135px, 1fr));
  }

  .coo-root .range-panel .range-apply {
    width: 100% !important;
  }
}

/* Mobile: one control per row. */
@media (max-width: 600px) {
  .coo-root .modal {
