  /* Back to ERPNext Healthcare workspace button under the COO title. */
  function ensureBackToHealthcareButton() {
    if (root.querySelector("[data-coo-back-to-app]")) {
      return true;
    }

    var titleText =
      "LIFE SLIMMING AND COSMETIC PVT. LTD.";

    var titleElement = null;
    var candidates = root.querySelectorAll(
      "h1,h2,h3,h4,strong,b,p,span,div"
