    for (var i = 0; i < candidates.length; i += 1) {
      var candidateText = String(
        candidates[i].textContent || ""
      ).replace(/\s+/g, " ").trim();

      if (candidateText === titleText) {
        titleElement = candidates[i];
        break;
      }
    }

    /* Fallback for a header where title and subtitle share one wrapper. */
    if (!titleElement) {
      var smallestMatch = null;
      var smallestLength = Infinity;

      for (var j = 0; j < candidates.length; j += 1) {
        var combinedText = String(
          candidates[j].textContent || ""
        ).replace(/\s+/g, " ").trim();

        if (
          combinedText.indexOf(titleText) !== -1 &&
