  }

  function ensureClientInfoFinanceCard() {
    var existing =
      root.querySelector('[data-tile="clientinfo"]');

    if (existing) return existing;

    /*
      Accounts, Branch Ranking and HR are already inside the
      Finance & Organisation grid. Clone HR's outer card so the new
