  }

  ensureClientInfoFinanceCard();

  /*
    Client Info is opened from a card under Finance & Organisation.
    No top-level dashboard tab is added.
  */

  /* ---------- config: verified against portal ---------- */
  var RPT_SALES = "CATEGORY & BRANCH WISE SALES \u2013 COLLECTION"; // en-dash
  var RPT_CC    = "CC Invoice Report";

  var BRANCHES = ["Banjara Hills","Chandanagar","Dilsukhnagar","Gachibowli","Himayathnagar",
                  "Kukatpally","Madhapur","Nellore","SR Nagar","Vijayawada","Vizag"];
  /* Head Office is required for Task Management / Tickets and is harmless for
     clinical/finance reports where it simply returns no rows. */
  var REPORT_BRANCHES = BRANCHES.concat(["Head Office"]);

  /* ============================================================
     REMOVE HEAD OFFICE FROM EVERY SELECT TAG
     ============================================================ */

  function normalizeCooSelectOptionText(value) {
    return String(value || "")
      .trim()
      .toLowerCase()
      .replace(/[^a-z0-9]+/g, "");
  }

  function isHeadOfficeSelectOption(optionElement) {
    if (!optionElement) {
      return false;
    }

    var optionValue = normalizeCooSelectOptionText(
      optionElement.value
    );

    var optionText = normalizeCooSelectOptionText(
      optionElement.textContent ||
      optionElement.innerText ||
      ""
    );

    return (
      optionValue === "headoffice" ||
      optionText === "headoffice"
    );
  }

  function removeHeadOfficeFromSelects(scope) {
    var host = scope || root;

    if (!host || !host.querySelectorAll) {
      return;
    }

    /*
     * Include the supplied node itself when it is a select or option,
     * then inspect every nested select. This handles:
     * - header dropdowns
     * - popup and modal filters
     * - Complete View filters
     * - dynamically injected Task, Ticket and HR controls
     * - controls added by later dashboard updates
     */
    var selects = [];

    if (
      host.matches &&
      host.matches("select")
    ) {
      selects.push(host);
    }

    host
      .querySelectorAll("select")
      .forEach(function (selectElement) {
        selects.push(selectElement);
      });

    selects.forEach(function (selectElement) {
      var previousValue = String(
        selectElement.value || ""
      );

      Array.prototype.slice
        .call(selectElement.options || [])
        .forEach(function (optionElement) {
          if (isHeadOfficeSelectOption(optionElement)) {
            optionElement.remove();
          }
        });

      /*
       * If Head Office had already been selected before its option
       * was removed, return the dropdown to All / its first option.
       */
      if (
        normalizeCooSelectOptionText(previousValue) ===
        "headoffice"
      ) {
        var allOption = Array.prototype.find.call(
          selectElement.options || [],
          function (optionElement) {
            return (
              normalizeCooSelectOptionText(
                optionElement.value
              ) === "all"
            );
          }
        );

        if (allOption) {
          selectElement.value = allOption.value;
        } else if (
          selectElement.options &&
          selectElement.options.length
        ) {
          selectElement.selectedIndex = 0;
        }
      }
    });
  }

  /*
   * Remove it immediately from HTML already present on page load.
   */
  removeHeadOfficeFromSelects(root);

  /*
   * Watch the complete COO page because many filters are generated only
   * after opening a modal or Complete View.
   */
  var COO_HEAD_OFFICE_SELECT_OBSERVER =
    new MutationObserver(function (mutations) {
      mutations.forEach(function (mutation) {
        Array.prototype.forEach.call(
          mutation.addedNodes || [],
          function (addedNode) {
