     embedded Task Manager HTML, CSS and JavaScript. No guessed route or Custom HTML Block lookup is used. */

  var state = { branch: "ALL", emp: "ALL", sales: null, inv: null,
                cc: null, grv: null, appt: null,
                session: null, plan: null, therapyType: null,
                appr: null, stock: null, hr: null, todo: null, asset: null,
                tick: null, pe: null, att: null, po: null, tgt: null,
                c2c: null, p2p: null, b2b: null,
                err: {}, loading: true, pageRanges: {}, pageData: {} };

  /* Performance guard: do not start a second full dashboard reload while one
