     from duplicating the same 20 server requests. */
  var COO_ACTIVE_LOAD = null;
  var COO_DASHBOARD_CACHE_MAX_AGE = 10 * 60 * 1000;

  /* Appointment popup only: session history loads after the popup is visible.
     It is not part of main COO startup, so browser refresh remains fast. */
  var APPOINTMENT_LAST_SESSION_KEY = "";
  var APPOINTMENT_LAST_SESSION_ROWS = [];
  var APPOINTMENT_LAST_SESSION_PROMISE = null;

  /* While a popup or Complete View is being rendered, these helpers make the
     report use its own date/branch selection. The main dashboard continues to
     use state.fromDate/state.toDate/state.branch. */
  var renderContextTile = "";

  function activeReportRange() {
    return renderContextTile && state.pageRanges[renderContextTile]
      ? state.pageRanges[renderContextTile]
      : null;
  }

  function effectiveBranch() {
    var local = activeReportRange();
    return (local && local.branch) || state.branch || "ALL";
  }

  /* ---------- helpers ---------- */
  /* the conversion stages are verbose ("Centre Manager Approval Pending") -> trim */
  function shortStage(s) {
    return String(s || "\u2014").replace(/\s*Approval Pending$/i, "")
      .replace(/\s*Final Decision Pending$/i, "").replace(/\s*Pending$/i, "").trim() || "\u2014";
  }

  function inr(n) { return "\u20B9" + Math.round(n || 0).toLocaleString("en-IN"); }
  function inrS(n) {
    n = n || 0;
