  }
  var CYC = cycle();
  void 0;

  /* One global From/To date range controls every date-aware dashboard tile. */
  state.fromDate = CYC.from;
  state.toDate = CYC.to;
  state.rangePreset = "cycle";
  state.tgtDocs = [];

  function rangeFrom() {
    var local = activeReportRange();
    return (local && local.from) || state.fromDate || CYC.from;
  }
  function rangeTo() {
    var local = activeReportRange();
    return (local && local.to) || state.toDate || CYC.to;
  }

  function formatBusinessDate(value) {
    var text = String(value || "").trim();
    var match = /^(\d{4})-(\d{2})-(\d{2})$/.exec(text);
    if (!match) return text || "—";

    var months = ["Jan", "Feb", "Mar", "Apr", "May", "Jun",
      "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"];
    var monthIndex = Number(match[2]) - 1;
    var year = match[1].slice(-2);
    return match[3] + "-" + (months[monthIndex] || match[2]) + "-" + year;
  }

  function rangeText() {
    var local = activeReportRange();
    if (local && local.preset === "coo-pending-all-dates") {
      return "COO Pending Records · All Dates";
