  }


  /* Fast browser refresh: keep only the already-rendered dashboard cards in
     sessionStorage. The page can display the last successful view immediately
     while fresh ERPNext data loads in the background. No report rows or client
     details are cached. */
  function dashboardCacheKey() {
    var user = (frappe.session && frappe.session.user) || "Guest";
    return "life_coo_dashboard_cards_v2_client_info_card|" + user + "|" + CYC.from + "|" + CYC.to;
  }

  function saveDashboardSnapshot() {
    if (state.loading || state.branch !== "ALL" || state.emp !== "ALL") return;
    try {
      var tiles = {};
      root.querySelectorAll("[data-tile]").forEach(function (tileNode) {
        var key = tileNode.getAttribute("data-tile");
        if (key) tiles[key] = tileNode.innerHTML;
      });
      var strip = $("[data-strip]");
      sessionStorage.setItem(dashboardCacheKey(), JSON.stringify({
        savedAt: Date.now(),
        fromDate: state.fromDate,
        toDate: state.toDate,
        strip: strip ? strip.innerHTML : "",
        tiles: tiles
      }));
    } catch (error) {
      void 0;
    }
  }

  function restoreDashboardSnapshot() {
    try {
      var raw = sessionStorage.getItem(dashboardCacheKey());
      if (!raw) return false;
      var snapshot = JSON.parse(raw);
      if (!snapshot || !snapshot.savedAt ||
          Date.now() - snapshot.savedAt > COO_DASHBOARD_CACHE_MAX_AGE ||
          snapshot.fromDate !== state.fromDate || snapshot.toDate !== state.toDate) {
        sessionStorage.removeItem(dashboardCacheKey());
        return false;
      }

      var restored = false;
      Object.keys(snapshot.tiles || {}).forEach(function (key) {
        var tileNode = root.querySelector('[data-tile="' + key + '"]');
        if (!tileNode) return;
        tileNode.innerHTML = snapshot.tiles[key];
        restored = true;
      });
      var strip = $("[data-strip]");
      if (strip && snapshot.strip) {
        strip.innerHTML = snapshot.strip;
        restored = true;
      }
      var liveLabel = $("[data-live-label]");
      if (liveLabel && restored) liveLabel.textContent = "Refreshing latest data...";
      return restored;
    } catch (error) {
      void 0;
      return false;
    }
