  function pad2(n) { return ("0" + n).slice(-2); }
  function ymd(d) {
    return d.getFullYear() + "-" + pad2(d.getMonth() + 1) + "-" + pad2(d.getDate());
  }
  function localDate(s) { return new Date(String(s) + "T00:00:00"); }
  function addDays(s, days) {
    var d = localDate(s);
    d.setDate(d.getDate() + days);
    return ymd(d);
  }
  function presetRange(name) {
    var today = CYC.today;
    var d = localDate(today);
    if (name === "today") return { from: today, to: today };
    if (name === "yesterday") {
      var y = addDays(today, -1);
      return { from: y, to: y };
    }
    if (name === "cycle") return { from: CYC.from, to: CYC.to };
    /* LIFE business month is always the 6th through the 5th. */
    if (name === "month") {
      return { from: CYC.from, to: CYC.to };
    }
    if (name === "last-month") {
      var currentCycleStart = localDate(CYC.from);
      var previousCycleStart = new Date(currentCycleStart);
      previousCycleStart.setMonth(previousCycleStart.getMonth() - 1);
      var previousCycleEnd = new Date(currentCycleStart);
      previousCycleEnd.setDate(previousCycleEnd.getDate() - 1);
      return { from: ymd(previousCycleStart), to: ymd(previousCycleEnd) };
    }
    return { from: rangeFrom(), to: rangeTo() };
  }

