  /* ---------- data: query_report.run ---------- */
  function runReport(name, filters) {
    return new Promise(function (resolve, reject) {
      frappe.call({
        method: "frappe.desk.query_report.run",
        args: { report_name: name, filters: filters, ignore_prepared_report: 1 },
        callback: function (r) {
          if (!r || !r.message) { reject("No response from " + name); return; }
          // report may append an array "Total" row -> keep only dict rows
          var rows = (r.message.result || []).filter(function (x) {
            return x && !Array.isArray(x) && typeof x === "object";
          });
          resolve(rows);
        },
        error: function (e) { reject((e && e.message) || ("Failed: " + name)); }
      });
    });
  }

  /* Employee dropdown: active staff, narrowed to the selected branch */
  function fillEmpSel() {
    var sel = $("[data-emp-sel]");
    if (!sel) {
      state.emp = "ALL";
      return;
    }
    var cur = state.emp;
    var names = {};
    (state.hr || []).forEach(function (r) {
      if (!activeAsOf(r, rangeTo())) return;
      if (!validHrBranch(r.branch)) return;
      if (state.branch !== "ALL" && r.branch !== state.branch) return;
      if (r.employee_name) names[r.employee_name] = 1;
    });
    /* CC agents come from the invoice report, not the Employee master */
    (state.cc || []).forEach(function (r) {
      if (state.branch !== "ALL" && r.branch !== state.branch) return;
      var a = (r.cc_agent || "").trim();
      if (a) names[a] = 1;
    });
    var list = Object.keys(names).sort();
    sel.innerHTML = '<option value="ALL">All Employees (' + list.length + ")</option>" +
      list.map(function (n) {
        return '<option value="' + esc(n) + '">' + esc(n) + "</option>";
      }).join("");
    /* keep the selection if it still exists in the narrowed list */
    sel.value = (cur !== "ALL" && names[cur]) ? cur : "ALL";
    if (sel.value === "ALL") state.emp = "ALL";
  }

  /*
   * TARGET SOURCE OF TRUTH
   * ----------------------
   * Target amounts come only from the child rows of:
   *   Week Target vs Achive With Cuttings
   *
   * Achievement is NOT taken from this DocType. It is calculated later from
   * submitted Receive Payment Entries, branch-wise.
   *
   * Normal payment mode:
   *   remove included 5% GST using amount × 100 ÷ 105.
   *
   * Loan / finance payment mode:
   *   1) deduct 15% loan processing amount from gross;
   *   2) deduct 5% from the remaining amount;
   *   3) use the final balance as achievement.
   */
  function combineTargetDocs(docs, fromDate, toDate) {
    var byBranch = {};

    (docs || []).forEach(function (d) {
      (d.week_target_vs_archive_details || []).forEach(function (r) {
        var branch = String(r.branch || "Unassigned").trim() || "Unassigned";
        if (!byBranch[branch]) {
          byBranch[branch] = {
            branch: branch,
            targeted_amount: 0
          };
        }
        byBranch[branch].targeted_amount += parseFloat(r.targeted_amount) || 0;
      });
    });

    var rows = Object.keys(byBranch).sort().map(function (branch) {
      return byBranch[branch];
    });

    var rowTarget = rows.reduce(function (a, r) {
      return a + (parseFloat(r.targeted_amount) || 0);
    }, 0);

    return {
      name: docs.length === 1 ? docs[0].name : docs.length + " target periods",
      from_date: fromDate,
      to_date: toDate,
      grand_total_targeted_amount: rowTarget,
      week_target_vs_archive_details: rows,
      _source_docs: docs.map(function (d) { return d.name; })
    };
  }

  /* Load all target documents that overlap the selected From/To dates. */
  function loadTargetRange(fromDate, toDate) {
    delete state.err.tgt;

    return new Promise(function (resolve) {
      frappe.call({
        method: "frappe.client.get_list",
        args: {
          doctype: "Week Target vs Achive With Cuttings",
          fields: ["name","from_date","to_date","grand_total_targeted_amount",
                   "grand_total_achievement_amount","grand_total_deficit",
                   "total_achievement_percentage","grand_total_asking_rate",
                   "grand_total_avg_per_day_achievement"],
          /* overlap rule: document starts before selected To and ends after selected From */
          filters: [["from_date","<=",toDate],["to_date",">=",fromDate]],
          limit_page_length: 100,
          order_by: "from_date asc"
        },
        callback: function (r) {
          var hits = (r && r.message) || [];
          if (!hits.length) {
            state.tgtDocs = [];
            state.tgt = null;
            resolve(0);
            return;
          }

          Promise.all(hits.map(function (hit) {
            return new Promise(function (done) {
              frappe.call({
                method: "frappe.client.get",
                args: { doctype: "Week Target vs Achive With Cuttings", name: hit.name },
                callback: function (d) { done((d && d.message) || null); },
                error: function () { done(null); }
              });
            });
          })).then(function (docs) {
            docs = docs.filter(function (d) { return !!d; });
            state.tgtDocs = docs;
            state.tgt = docs.length ? combineTargetDocs(docs, fromDate, toDate) : null;
            resolve(docs.length);
          });
        },
        error: function () {
          state.err.tgt = "Target data unavailable (check permissions)";
          state.tgtDocs = [];
          state.tgt = null;
          resolve(0);
        }
      });
    });
  }



  /* Fetch target documents for a popup-specific range without changing the
     main dashboard target state. */
  function fetchTargetRangeData(fromDate, toDate) {
    return new Promise(function (resolve) {
      frappe.call({
        method: "frappe.client.get_list",
        args: {
          doctype: "Week Target vs Achive With Cuttings",
          fields: ["name", "from_date", "to_date", "grand_total_targeted_amount"],
          filters: [["from_date", "<=", toDate], ["to_date", ">=", fromDate]],
          limit_page_length: 100,
          order_by: "from_date asc"
        },
        callback: function (response) {
          var hits = (response && response.message) || [];
          if (!hits.length) {
            resolve({ ok: true, data: null });
            return;
          }
          Promise.all(hits.map(function (hit) {
            return new Promise(function (done) {
              frappe.call({
                method: "frappe.client.get",
                args: { doctype: "Week Target vs Achive With Cuttings", name: hit.name },
                callback: function (docResponse) {
                  done((docResponse && docResponse.message) || null);
                },
                error: function () { done(null); }
              });
            });
          })).then(function (docs) {
            docs = docs.filter(function (doc) { return !!doc; });
            resolve({
              ok: true,
              data: docs.length ? combineTargetDocs(docs, fromDate, toDate) : null
            });
          });
        },
        error: function (error) {
          void 0;
          resolve({ ok: false, data: null });
        }
      });
    });
  }

