  function documentCompanyAmount(row) {
    row = row || {};

    var roundedEnabled =
      Number(row.disable_rounded_total || 0) !== 1;

    var baseRounded =
      parseFloat(row.base_rounded_total);

    var baseGrand =
      parseFloat(row.base_grand_total);

    var rounded =
      parseFloat(row.rounded_total);

    var grand =
      parseFloat(row.grand_total);

    if (
      roundedEnabled &&
      Number.isFinite(baseRounded) &&
      baseRounded !== 0
    ) {
      return baseRounded;
    }

    if (Number.isFinite(baseGrand)) {
      return baseGrand;
    }

    if (
      roundedEnabled &&
      Number.isFinite(rounded) &&
      rounded !== 0
    ) {
      return rounded;
    }

    return Number.isFinite(grand) ? grand : 0;
  }

  function salesInvoiceCollected(row) {
    var total =
      documentCompanyAmount(row);

    var outstanding =
      parseFloat(
        (row && row.outstanding_amount) || 0
      ) || 0;

    return Math.max(
      total - Math.max(outstanding, 0),
      0
    );
  }

  function localSalesInvoiceRows() {
    var tileKey =
      canonicalSalesRangeTile(
        renderContextTile
      );

    if (
      !tileKey ||
      !state.pageData ||
      !state.pageData[tileKey] ||
      !Array.isArray(
        state.pageData[tileKey].invoices
      )
    ) {
      return null;
    }

    var range =
      appointmentPageRange(
        tileKey
      );

    var branch =
      range.branch ||
      effectiveBranch();

    return state.pageData[
      tileKey
    ].invoices.filter(function (row) {
      var postingDate =
        String(
          row.posting_date ||
          ""
        ).slice(0, 10);

      var branchMatches =
        branch === "ALL" ||
        String(row.branch || "") === branch;

      return (
        postingDate &&
        (!range || (
          postingDate >= range.from &&
          postingDate <= range.to
        )) &&
        branchMatches &&
        Number(row.docstatus) === 1 &&
        Number(row.is_return || 0) !== 1
      );
    });
  }

  function salesInvoiceNetAmount(row) {
    row = row || {};

    var baseNet =
      parseFloat(row.base_net_total);

    var net =
      parseFloat(row.net_total);

    if (Number.isFinite(baseNet)) {
      return baseNet;
    }

    if (Number.isFinite(net)) {
      return net;
    }

    return removeGST5(
      documentCompanyAmount(row)
    );
