  function salesInvoiceTaxAmount(row) {
    row = row || {};

    var baseTax =
      parseFloat(
        row.base_total_taxes_and_charges
      );

    var tax =
      parseFloat(
        row.total_taxes_and_charges
      );

    if (Number.isFinite(baseTax)) {
      return baseTax;
    }

    if (Number.isFinite(tax)) {
      return tax;
    }

    return Math.max(
      documentCompanyAmount(row) -
      salesInvoiceNetAmount(row),
      0
    );
  }

