  function grvRows() { return (state.grv || []).filter(function (r) { return inBr(r.branch); }); }

  /* Bin.warehouse is "Banjara Hills - LSACPL" -> strip company suffix */
  function whBranch(w) { return String(w || "").replace(/\s*-\s*LSACPL\s*$/i, "").trim(); }
  /* Asset.location is UPPERCASE and abbreviated ("BANJARA") -> match loosely */
  function locBranch(l) {
    var s = String(l || "").trim().toUpperCase();
    if (!s) return "";
    for (var i = 0; i < BRANCHES.length; i++) {
      var b = BRANCHES[i].toUpperCase();
      if (s === b || s.indexOf(b) === 0 || b.indexOf(s) === 0) return BRANCHES[i];
      var first = b.split(" ")[0];
      if (s === first || s.indexOf(first) === 0) return BRANCHES[i];
    }
    return String(l).trim();
  }
  /* LIFE Task Manager stores its report fields inside a JSON comment in ToDo.description. */
  function parseLifeMeta(description, type) {
    var re = new RegExp("<!--LIFE_" + type + "_META:([\\s\\S]*?)-->");
    var match = String(description || "").match(re);
    if (!match) return {};
    try { return JSON.parse(match[1]) || {}; }
    catch (error) { return {}; }
  }

  function cleanLifeDescription(description) {
    return String(description || "")
      .replace(/<!--LIFE_[A-Z]+_META:[\s\S]*?-->/g, "")
      .replace(/<br\s*\/?>/gi, "\n")
      .replace(/<\/p>/gi, "\n")
      .replace(/<\/div>/gi, "\n")
      .replace(/<\/li>/gi, "\n")
      .replace(/<li[^>]*>/gi, "\u2022 ")
      .replace(/<[^>]*>/g, " ")
      .replace(/&nbsp;/gi, " ")
      .replace(/&amp;/gi, "&")
      .replace(/&lt;/gi, "<")
      .replace(/&gt;/gi, ">")
      .replace(/&quot;/gi, '"')
      .replace(/&#039;/gi, "'")
      .replace(/[ \t]+/g, " ")
      .replace(/\n\s+/g, "\n")
      .replace(/\n{3,}/g, "\n\n")
      .trim();
  }

  function ticketDetailsText(description) {
