   * Therapy Session (docstatus = 1) matches it. Exact session.appointment
   * is preferred; older unlinked sessions use same date/client/branch and
   * then prefer Therapy Plan, therapy type and closest time.
   */
  function serviceMatchText(value) {
    return String(value || "").trim().toLowerCase().replace(/\s+/g, " ");
  }

  function serviceMatchCompact(value) {
    return serviceMatchText(value).replace(/[^a-z0-9]+/g, "");
  }

  function serviceTimeMinutes(value) {
    var match = /^(\d{1,2}):(\d{2})/.exec(String(value || "").trim());
    return match ? Number(match[1]) * 60 + Number(match[2]) : null;
  }

  function servicePatientKeys(row) {
    var keys = [];
    [row && row.patient, row && row.patient_name].forEach(function (value) {
      var key = serviceMatchCompact(value);
      if (key && keys.indexOf(key) < 0) keys.push(key);
    });
    return keys;
  }

  function serviceKeysOverlap(left, right) {
    return left.some(function (key) { return right.indexOf(key) >= 0; });
  }

  function appointmentPlanKey(row) {
    return serviceMatchCompact(row && (row.therapy_plan_1 || row.therapy_plan));
  }

  function sessionPlanKey(row) {
    return serviceMatchCompact(row && row.therapy_plan);
  }

  function appointmentTherapyKey(row) {
    return serviceMatchCompact(row &&
      (row.therapy_type1 || row.therapy_type || row.concern));
  }

  function sessionTherapyKey(row) {
    return serviceMatchCompact(row && (row.therapy_type || row.service_unit));
  }

  function serviceAppointmentSessionScore(appointment, session) {
    if (String(appointment.appointment_date || "").slice(0, 10) !== sessionDate(session)) {
      return -1;
    }

    var appointmentPatients = servicePatientKeys(appointment);
    var sessionPatients = servicePatientKeys(session);
    if (!appointmentPatients.length || !sessionPatients.length ||
        !serviceKeysOverlap(appointmentPatients, sessionPatients)) {
      return -1;
    }

    var score = 100;
    var appointmentBranch = serviceMatchCompact(appointment.branch);
    var sessionBranch = serviceMatchCompact(session.branch);
    if (appointmentBranch && sessionBranch) {
      if (appointmentBranch !== sessionBranch) return -1;
      score += 30;
    }

    var apptPlan = appointmentPlanKey(appointment);
    var sessionPlan = sessionPlanKey(session);
    if (apptPlan && sessionPlan) {
      score += apptPlan === sessionPlan ? 120 : -25;
    }

    var apptTherapy = appointmentTherapyKey(appointment);
    var sessionTherapy = sessionTherapyKey(session);
    if (apptTherapy && sessionTherapy) {
      if (apptTherapy === sessionTherapy) score += 70;
      else if (apptTherapy.indexOf(sessionTherapy) >= 0 ||
               sessionTherapy.indexOf(apptTherapy) >= 0) score += 35;
    }

    var apptMinutes = serviceTimeMinutes(appointment.appointment_time);
    var sessionMinutes = serviceTimeMinutes(session.custom_in_time_ || session.start_time);
    if (apptMinutes !== null && sessionMinutes !== null) {
      score += Math.max(0, 30 - Math.min(Math.abs(apptMinutes - sessionMinutes), 30));
    }

    return score;
  }

  function matchBookedAppointmentsToSessions(bookedRows, sessionRows) {
    var matches = [];
    var usedAppointments = {};
    var usedSessions = {};
    var appointmentByName = {};
    var candidateIndex = {};

    /* Build a date + client index once. The old version compared every session
       with every appointment (roughly 4,000 x 700 comparisons on this page).
       This index keeps the same matching rules but scores only realistic
       candidates for the same date and client. */
    bookedRows.forEach(function (appointment, index) {
      var name = String(appointment.name || "");
      if (name) appointmentByName[name] = { row: appointment, index: index };

      var date = String(appointment.appointment_date || "").slice(0, 10);
      servicePatientKeys(appointment).forEach(function (patientKey) {
        var indexKey = date + "|" + patientKey;
        if (!candidateIndex[indexKey]) candidateIndex[indexKey] = [];
        candidateIndex[indexKey].push(index);
      });
    });

    /* Exact Therapy Session.appointment link always wins. */
    sessionRows.forEach(function (session, sessionIndex) {
      var linked = appointmentByName[String(session.appointment || "").trim()];
      if (!linked || usedAppointments[linked.index]) return;
      usedAppointments[linked.index] = true;
      usedSessions[sessionIndex] = true;
      matches.push({ appointment: linked.row, session: session,
        match_type: "appointment_link" });
    });

    /* Older unlinked sessions use the same fallback score as before, but only
       against appointments sharing the same date and client key. */
    sessionRows.forEach(function (session, sessionIndex) {
      if (usedSessions[sessionIndex]) return;

      var sessionDateValue = sessionDate(session);
      var candidateMap = {};
      servicePatientKeys(session).forEach(function (patientKey) {
        (candidateIndex[sessionDateValue + "|" + patientKey] || [])
          .forEach(function (appointmentIndex) {
            candidateMap[appointmentIndex] = true;
          });
      });

      var bestIndex = -1;
      var bestScore = -1;
      Object.keys(candidateMap).forEach(function (candidateIndexText) {
        var appointmentIndex = Number(candidateIndexText);
        if (usedAppointments[appointmentIndex]) return;
        var appointment = bookedRows[appointmentIndex];
        var score = serviceAppointmentSessionScore(appointment, session);
        if (score > bestScore) {
          bestScore = score;
          bestIndex = appointmentIndex;
        }
      });

      if (bestIndex >= 0 && bestScore >= 100) {
        usedAppointments[bestIndex] = true;
        usedSessions[sessionIndex] = true;
        matches.push({ appointment: bookedRows[bestIndex], session: session,
          match_type: "client_date_fallback" });
      }
    });

    return {
      matches: matches,
      pendingAppointments: bookedRows.filter(function (row, index) {
        return !usedAppointments[index];
      }),
      unmatchedSessions: sessionRows.filter(function (row, index) {
        return !usedSessions[index];
      })
    };
  }

  function appointmentSessionMatchData(appointments, suppliedSessions) {
    appointments = Array.isArray(appointments) ? appointments : [];
    var sessions = Array.isArray(suppliedSessions)
      ? suppliedSessions
      : appointmentSessionRows();

    /* Cancelled and no-show appointments are intentionally not treated as
       executed. Every execution must come from one submitted Therapy Session. */
    var executionEligible = appointments.filter(function (row) {
      return !isAppointmentCancelled(row) && !isAppointmentNoShow(row);
    });

    var result = matchBookedAppointmentsToSessions(executionEligible, sessions);
    var byAppointment = {};

    result.matches.forEach(function (pair) {
      var appointmentName = String(pair.appointment && pair.appointment.name || "");
      if (appointmentName) byAppointment[appointmentName] = pair.session;
    });

    return {
      byAppointment: byAppointment,
      entered: result.matches.length,
      notEntered: Math.max(appointments.length - result.matches.length, 0),
      matches: result.matches
    };
  }

  function appointmentSessionCell(session) {
    if (!session) {
      return '<span class="pill p-r">Not Entered</span>';
    }

    return '<span class="pill p-g">Entered</span>' +
      '<div class="wm">' + esc(session.name || "Therapy Session") + '</div>';
  }

  function appointmentDetailSessionRows() {
    var combined = [];
    var seen = {};

    [appointmentSessionRows(), serviceSessionRows(), state.session || []]
      .forEach(function (rows) {
        (rows || []).forEach(function (row) {
          var key = String(row && row.name || "");
          if (!key || seen[key]) return;
          seen[key] = true;
          combined.push(row);
