      });

    return combined;
  }

  function serviceSummary(useLocalRange) {
    var appointments = useLocalRange
      ? appointmentPageRows("service")
      : apptRows();

    var bookedRows = appointments.filter(isServiceBookedAppointment);
    var noShowRows = bookedRows.filter(isAppointmentNoShow);
    var executionEligibleRows = bookedRows.filter(function (row) {
      return !isAppointmentNoShow(row);
    });

    var submittedSessions = useLocalRange
      ? serviceSessionRows()
      : (state.session || []).filter(function (r) {
          return inBr(r.branch) && Number(r.docstatus || 0) === 1;
        });

    var matchResult = matchBookedAppointmentsToSessions(
      executionEligibleRows,
      submittedSessions
    );
    var matches = matchResult.matches;
    var pendingRows = matchResult.pendingAppointments;
    var matchedSessions = matches.map(function (pair) {
      pair.session._matched_appointment = pair.appointment;
      pair.session._service_match_type = pair.match_type;
      return pair.session;
    });

    var booked = bookedRows.length;
    var done = matches.length;
    var noShow = noShowRows.length;
    var pending = pendingRows.length;
    var utilisation = Math.min(pct(done, done + pending || done), 100);
    var byDepartment = {};

    bookedRows.forEach(function (appointment) {
      var department = serviceDepartmentFromAppointment(appointment);
      if (!byDepartment[department]) {
        byDepartment[department] = { n: department, booked: 0, done: 0,
          pending: 0, noShow: 0 };
      }
      byDepartment[department].booked += 1;
      if (isAppointmentNoShow(appointment)) byDepartment[department].noShow += 1;
    });

    matches.forEach(function (pair) {
      var department = serviceDepartmentFromAppointment(pair.appointment);
      if (!byDepartment[department]) {
        byDepartment[department] = { n: department, booked: 0, done: 0,
          pending: 0, noShow: 0 };
      }
      byDepartment[department].done += 1;
    });

    pendingRows.forEach(function (appointment) {
      var department = serviceDepartmentFromAppointment(appointment);
      if (!byDepartment[department]) {
        byDepartment[department] = { n: department, booked: 0, done: 0,
          pending: 0, noShow: 0 };
      }
      byDepartment[department].pending += 1;
    });

    var departments = Object.keys(byDepartment).map(function (key) {
      var row = byDepartment[key];
      row.rate = Math.min(pct(row.done, row.done + row.pending || row.done), 100);
      return row;
    }).sort(function (a, b) {
      return b.booked - a.booked || b.done - a.done || a.n.localeCompare(b.n);
    });

    return {
      appointments: appointments,
      bookedRows: bookedRows,
      executionEligibleRows: executionEligibleRows,
      matches: matches,
      sessions: matchedSessions,
      submittedSessions: submittedSessions,
      unmatchedSessions: matchResult.unmatchedSessions,
      pendingRows: pendingRows,
      noShowRows: noShowRows,
      booked: booked,
      done: done,
      noShow: noShow,
      pending: pending,
      utilisation: utilisation,
      departments: departments,
      expiring: serviceExpiringPlans(!!useLocalRange)
    };
  }

  function findAppointmentByName(name) {
    var serviceLocal = state.pageData && state.pageData.service;
    var serviceAppointments =
      serviceLocal && !Array.isArray(serviceLocal)
        ? (serviceLocal.appointments || [])
        : [];
    var rows = appointmentSourceRows("appointments")
      .concat(serviceAppointments)
      .concat(state.appt || []);

    for (var i = 0; i < rows.length; i++) {
      if (rows[i] && rows[i].name === name) return rows[i];
    }
    return null;
  }

  function apptRows() {
    return (state.appt || []).filter(function (r) { return inBr(r.branch); });
  }
  function approvalRowInActiveRange(row, fields) {
    var local = activeReportRange();
    if (!local) return true;

    /* My Approvals > COO Pending Records (All Dates) ignores the date range. */
    if (local.preset === "coo-pending-all-dates") return true;

    var value = "";
    (fields || []).some(function (field) {
      if (row && row[field]) {
        value = String(row[field]).slice(0, 10);
        return true;
      }
      return false;
    });

    if (!value) return true;
    return value >= local.from && value <= local.to;
  }

  function approvalSourceRows(key) {
    var local =
      renderContextTile === "approvals" &&
      state.pageData &&
      state.pageData.approvals;

    if (local && Array.isArray(local[key])) {
