  function discountApprovalBranch(row) {
    row = row || {};

    /* 1) Branch saved directly on the Discount Approval Request. */
    var directBranch = String(row.branch || "").trim();
    if (directBranch) return directBranch;

    /* 2) Exact branch resolved from the linked Sales Invoice. */
    var resolvedBranch = String(row._resolved_branch || "").trim();
    if (resolvedBranch) return resolvedBranch;

    /* 3) Fallback to the already-loaded Sales Invoice register. */
    var invoiceName = String(row.linked_invoice || "").trim();
    if (!invoiceName) return "";

    var invoices = state.inv || [];
    var invoice = invoices.filter(function (inv) {
      return String(inv.name || "").trim() === invoiceName;
    })[0];

    if (!invoice) return "";

    return String(
      invoice.branch ||
      invoice.custom_transfer_branch ||
      ""
    ).trim();
  }

  /*
    Resolve blank Discount Approval branches by querying the exact linked
    Sales Invoice names. This does not depend on the dashboard's 5,000-row
    invoice register, so a current approval can never miss its invoice merely
    because that invoice was outside a prefetched page.
  */
  function hydrateDiscountApprovalBranches(rows) {
    rows = Array.isArray(rows) ? rows : [];
    if (!rows.length) return Promise.resolve(rows);

    var loadedInvoiceMap = {};
    (state.inv || []).forEach(function (invoice) {
      var name = String(invoice.name || "").trim();
      if (name) loadedInvoiceMap[name] = invoice;
    });

    var missing = {};

    rows.forEach(function (row) {
      if (!row || String(row.branch || "").trim()) return;

      var invoiceName = String(row.linked_invoice || "").trim();
      if (!invoiceName) return;

      var cached = loadedInvoiceMap[invoiceName];
      var cachedBranch = cached
        ? String(cached.branch || cached.custom_transfer_branch || "").trim()
        : "";

      if (cachedBranch) {
        row._resolved_branch = cachedBranch;
      } else {
        missing[invoiceName] = true;
      }
    });

    var invoiceNames = Object.keys(missing);
    if (!invoiceNames.length) return Promise.resolve(rows);

    /* Keep the IN filter small even if many approvals are opened together. */
    var chunks = [];
    for (var i = 0; i < invoiceNames.length; i += 100) {
      chunks.push(invoiceNames.slice(i, i + 100));
    }

    return Promise.all(chunks.map(function (names) {
      return new Promise(function (resolve) {
        frappe.call({
          method: "frappe.client.get_list",
          args: {
            doctype: "Sales Invoice",
            fields: [
              "name",
              "branch",
              "custom_transfer_branch",
              "therapy_plan_reference_id",
              "patient"
            ],
            filters: [["name", "in", names]],
            limit_page_length: names.length
          },
          callback: function (response) {
            resolve((response && response.message) || []);
          },
          error: function (error) {
            void 0;
            resolve([]);
          }
        });
      });
    })).then(function (batches) {
      var exactInvoiceMap = {};

      batches.forEach(function (batch) {
        (batch || []).forEach(function (invoice) {
          var name = String(invoice.name || "").trim();
          if (name) exactInvoiceMap[name] = invoice;
        });
      });

      rows.forEach(function (row) {
        if (!row || String(row.branch || "").trim() || String(row._resolved_branch || "").trim()) {
          return;
        }

        var invoiceName = String(row.linked_invoice || "").trim();
        var invoice = exactInvoiceMap[invoiceName];
        if (!invoice) return;

        row._resolved_branch = String(
          invoice.branch || invoice.custom_transfer_branch || ""
        ).trim();
      });

      void 0;

      return rows;
    });
  }

  function apprRows() {
    return approvalSourceRows("appr").filter(function (r) {
