  function isDiscountApprovalPending(row) {
    return String((row && row.status) || "").trim().toLowerCase() === "pending";
  }

  /*
    Discount Approval Request stores the requested values and the final
    approved values in different fields. Approved rows must show the actual
    approved percentage and amount instead of the earlier proposed values.
  */
  function discountApprovalPercent(row) {
    row = row || {};
    var status = String(row.status || "").trim().toLowerCase();
    var approved = parseFloat(row.approved_discount_pct);
    var requested = parseFloat(row.requested_discount_pct);

    if (status === "approved" && Number.isFinite(approved)) {
      return approved;
    }

    return Number.isFinite(requested) ? requested : 0;
  }

  function discountApprovalFinalAmount(row) {
    row = row || {};
    var status = String(row.status || "").trim().toLowerCase();
    var approved = parseFloat(row.approved_final_amount);
    var proposed = parseFloat(row.proposed_final_amount);
    var requested = parseFloat(row.requested_final_amount);
    var billTotal = parseFloat(row.bill_total) || 0;
    var discountPercent = discountApprovalPercent(row);

    if (status === "approved" && Number.isFinite(approved)) {
      return approved;
    }

    if (Number.isFinite(proposed) && proposed > 0) {
      return proposed;
    }

    if (Number.isFinite(requested) && requested > 0) {
      return requested;
    }

    if (billTotal > 0 && discountPercent > 0) {
      return billTotal - (billTotal * discountPercent / 100);
    }

    return 0;
  }

  function discountApprovalDecisionBy(row) {
    row = row || {};
    return String(
      row.approved_by ||
      row.rejected_by ||
      ""
    ).trim();
  }

  function discountApprovalDecisionAt(row) {
