  function isPurchaseOrderApprovalPending(row) {
    row = row || {};

    var docstatus =
      Number(row.docstatus || 0);

    if (docstatus === 2) {
      return false;
    }

    var workflowState =
      String(row.workflow_state || "")
        .trim()
        .toLowerCase();

    var erpStatus =
      String(row.status || "")
        .trim()
        .toLowerCase();

    var finalWorkflowStates = [
      "approved",
      "final approved",
      "fully approved",
      "submitted",
      "completed",
      "closed",
      "cancelled",
      "canceled",
      "rejected",
      "stopped"
    ];

    if (
      finalWorkflowStates.indexOf(
        workflowState
      ) >= 0
    ) {
      return false;
    }

    /*
      All unsent Purchase Orders are still pending action for COO:
        - ordinary Draft Purchase Orders
        - Purchase Orders already inside an approval workflow
          such as Pending Ops Approval

      This restores the complete pending PO count instead of showing only
      records whose workflow_state contains "Pending".
    */
    if (docstatus === 0) {
      return (
        erpStatus !== "cancelled" &&
        erpStatus !== "canceled" &&
        erpStatus !== "closed" &&
        erpStatus !== "completed"
      );
    }

    /*
      A submitted Purchase Order is included only when its workflow state
      explicitly says that approval/review is still pending. Normal submitted
      POs such as To Receive and Bill are not COO approvals.
    */
    return (
      workflowState.indexOf("pending") >= 0 ||
      workflowState.indexOf("awaiting") >= 0 ||
      workflowState.indexOf("for approval") >= 0 ||
      workflowState.indexOf("to approve") >= 0 ||
      workflowState.indexOf("review") >= 0 ||
      workflowState.indexOf("verification") >= 0 ||
      workflowState.indexOf("approval required") >= 0
    );
  }

  function allPurchaseOrderRows() {
    /* Purchase Order has no reliable branch field in the current COO source. */
    return approvalSourceRows("po").filter(function (row) {
      return approvalRowInActiveRange(
        row,
        ["transaction_date", "creation"]
      );
    });
  }

  function poRows() {
    return allPurchaseOrderRows().filter(isPurchaseOrderApprovalPending);
  }

  function selectedBranchMatchesEither(fromBranch, toBranch) {
    var branch = effectiveBranch();
    return branch === "ALL" || fromBranch === branch || toBranch === branch;
  }

  function c2cRows() {
    return approvalSourceRows("c2c").filter(function (r) {
      return selectedBranchMatchesEither(r.branch, r.receiving_branch) &&
        approvalRowInActiveRange(r, ["date", "creation"]);
    });
  }

  function c2cStatus(row) {
    return String(
      (row && (
        row.approval_stage ||
        row.approval_display_status ||
        row.conversion_status
      )) ||
      ""
    ).trim();
  }

  function isC2cPending(row) {
    var status = c2cStatus(row).toLowerCase();
    var finalStatus = String(
      (row && row.final_approval_status) ||
      ""
    ).trim().toLowerCase();

    return finalStatus !== "approved" &&
      finalStatus !== "rejected" &&
      status.indexOf("approved") === -1 &&
      status.indexOf("rejected") === -1 &&
      status.indexOf("completed") === -1;
  }

  function pendingC2cRows() {
    return c2cRows().filter(isC2cPending);
  }

  function p2pRows() {
    return approvalSourceRows("p2p").filter(function (r) {
      return inBr(r.branch) && approvalRowInActiveRange(r, ["creation"]);
    });
  }

  function b2bStatus(row) {
    var finalStatus = String((row && row.final_approval_status) || "").trim();

    if (finalStatus.toLowerCase() === "approved") {
      return "Approved / Transfer Completed";
    }

    return String(
      (row && row.approval_display_status) ||
      finalStatus ||
      "Branch Manager Approval Pending"
    ).trim();
  }

  function b2bRows() {
    return approvalSourceRows("b2b").filter(function (r) {
      return selectedBranchMatchesEither(
        r.transfer_from_branch,
        r.transfer_to_branch
      ) && approvalRowInActiveRange(
        r,
        ["date_of_transfer_request", "creation"]
      );
    });
  }

  function isB2bPending(row) {
    var status = b2bStatus(row).toLowerCase();
    return status !== "approved" &&
      status.indexOf("completed") === -1 &&
      status.indexOf("approved / transfer") === -1 &&
      status.indexOf("rejected") === -1;
  }

  function pendingB2bRows() {
    return b2bRows().filter(isB2bPending);
  }

  function p2pStatus(row) {
    return String(
      (row && (
        row.final_approval_status ||
        row.approval_display_status ||
        row.approval_stage ||
        row.automation_status
      )) ||
      ""
    ).trim();
  }

function approvalStatusText(kind, row) {
  row = row || {};

  var raw = String(
    row.approval_display_status ||
    row.workflow_state ||
    row.conversion_status ||
    row.approval_stage ||
    row.automation_status ||
    row.final_approval_status ||
    row.audit_status ||
    row.status ||
    ""
  ).trim();

  var text = raw.toLowerCase();

  /*
   * P2P / C2C / B2B display mapping:
   * Operations Head is the Audit stage in the LIFE approval flow.
   * Change only the visible dashboard label.
   */
  if (kind === "p2p" || kind === "c2c" || kind === "b2b") {
    var operationsApproved =
      text.indexOf("approved / operations head") >= 0 ||
      text.indexOf("operations head approved") >= 0 ||
      text.indexOf("approved by operations head") >= 0 ||
      (
        text.indexOf("approved") >= 0 &&
        text.indexOf("operations head") >= 0
      );

    var operationsPending =
      text.indexOf("operations head approval pending") >= 0 ||
      text.indexOf("operations approval pending") >= 0 ||
      text.indexOf("pending operations head") >= 0;

    if (operationsApproved || operationsPending) {
      return "Audit Pending";
    }

    if (
      text.indexOf("audit team approval pending") >= 0 ||
      text.indexOf("audit approval pending") >= 0 ||
      text.indexOf("audit verification pending") >= 0
    ) {
      return "Audit Pending";
    }

    if (
      text.indexOf("centre manager approval pending") >= 0 ||
      text.indexOf("center manager approval pending") >= 0 ||
      text.indexOf("cm approval pending") >= 0
    ) {
      return "CM Pending";
    }

    if (
      text.indexOf("coo / management approval pending") >= 0 ||
      text.indexOf("coo approval pending") >= 0 ||
      text.indexOf("coo final approval pending") >= 0
    ) {
      return "COO Pending";
    }
  }

  return raw || "—";
}


  /*
    V30 STRICT COO-PENDING RULES
    ----------------------------
    My Approvals must contain only records that are waiting for the COO / final
    management action. Earlier code treated every Draft PO and every pending B2B
    stage (Branch Manager / Audit / COO) as a COO approval, which inflated the
    count and showed records that the COO could not act on yet.
  */
  function isPurchaseOrderCooPending(row) {
    row = row || {};

    if (Number(row.docstatus || 0) === 2) return false;

    var workflowState = String(row.workflow_state || "")
      .trim()
      .toLowerCase();

    if (!workflowState) return false;

    return [
      "pending ops approval",
      "pending operations approval",
      "operations approval pending",
      "pending coo approval",
      "coo approval pending",
      "coo final approval pending",
      "pending management approval",
      "management approval pending"
    ].some(function (token) {
      return workflowState.indexOf(token) >= 0;
    });
  }

  function isB2bCooPending(row) {
    row = row || {};

    var finalStatus = String(row.final_approval_status || "")
      .trim()
      .toLowerCase();

    if (
      finalStatus === "approved" ||
      finalStatus === "rejected" ||
      finalStatus === "cancelled" ||
      finalStatus === "canceled"
    ) {
      return false;
    }

    var combined = [
      row.approval_display_status,
      row.approval_stage,
      row.workflow_state,
      row.status,
      row.audit_status,
      row.automation_status
    ].map(function (value) {
      return String(value || "").trim().toLowerCase();
    }).join(" ");

    return [
      "coo / management approval pending",
      "coo management approval pending",
      "coo / final approval pending",
      "coo final approval pending",
      "coo approval pending",
      "operations coo final decision pending",
      "management approval pending"
    ].some(function (token) {
      return combined.indexOf(token) >= 0;
    });
  }

  function approvalCurrentActionRequired(kind, row) {
    row = row || {};

    if (kind === "disc") {
      return (
        String(row.status || "").trim().toLowerCase() === "pending" &&
        String(row.approval_level || "").trim().toUpperCase() === "L4"
      );
    }

    if (kind === "po") {
      return isPurchaseOrderCooPending(row);
    }

    if (kind === "c2c") {
      return String(row.approval_stage || "")
        .trim().toLowerCase() === "operations coo final decision pending";
    }

    if (kind === "p2p") {
      return String(row.approval_stage || "")
        .trim().toLowerCase() === "coo / management approval pending";
    }

    if (kind === "b2b") {
      return isB2bCooPending(row);
    }

    return false;
  }

  function approvalStateCategory(kind, row) {
    row = row || {};

    var status = String(row.status || "").trim().toLowerCase();
    var workflowState = String(row.workflow_state || "").trim().toLowerCase();
    var approvalStage = String(row.approval_stage || "").trim().toLowerCase();
    var displayStatus = String(row.approval_display_status || "").trim().toLowerCase();
    var finalStatus = String(row.final_approval_status || "").trim().toLowerCase();
    var conversionStatus = String(row.conversion_status || "").trim().toLowerCase();
    var automationStatus = String(row.automation_status || "").trim().toLowerCase();
    var auditStatus = String(row.audit_status || "").trim().toLowerCase();

    var combined = [
      status,
      workflowState,
      approvalStage,
      displayStatus,
      finalStatus,
      conversionStatus,
      automationStatus,
      auditStatus
    ].join(" ");

    function hasAny(tokens) {
      return tokens.some(function (token) {
        return combined.indexOf(token) >= 0;
      });
    }

    /*
      A final rejection always wins, even when another old field still contains
      an earlier pending stage.
    */
    if (
      Number(row.docstatus || 0) === 2 ||
      finalStatus === "rejected" ||
      approvalStage === "rejected" ||
      conversionStatus === "rejected" ||
      status === "rejected" ||
      status === "cancelled" ||
      status === "canceled" ||
      hasAny(["rejected", "declined", "cancelled", "canceled", "stopped"])
    ) {
      return "REJECTED";
    }

    if (kind === "disc") {
      if (status === "approved") return "APPROVED";
      if (status === "pending" || status === "draft" || !status) return "PENDING";
      return "OTHER";
    }

    if (kind === "c2c") {
      if (
        finalStatus === "approved" ||
        approvalStage === "approved" ||
        conversionStatus === "approved" ||
        conversionStatus === "completed" ||
        hasAny(["process completed", "conversion completed"])
      ) {
        return "APPROVED";
      }

      return hasAny([
        "pending", "awaiting", "draft", "not started", "processing",
        "in progress", "review", "verification", "approval required"
      ]) ? "PENDING" : "OTHER";
    }

    if (kind === "p2p") {
      if (
        finalStatus === "approved" ||
        approvalStage === "approved" ||
        hasAny(["process completed", "conversion completed"])
      ) {
        return "APPROVED";
      }

      return hasAny([
        "pending", "awaiting", "draft", "not started", "processing",
        "in progress", "review", "verification", "approval required"
      ]) ? "PENDING" : "OTHER";
    }

    if (kind === "b2b") {
      if (
        finalStatus === "approved" ||
        approvalStage === "approved" ||
        hasAny(["transfer completed", "process completed"])
      ) {
        return "APPROVED";
      }

      return hasAny([
        "pending", "awaiting", "draft", "not started", "processing",
        "in progress", "review", "verification", "approval required"
      ]) ? "PENDING" : "OTHER";
    }

    if (kind === "po") {
      /*
        Submitted Purchase Orders can still be inside a pending workflow.
        Check the existing COO pending rule before classifying docstatus = 1
        as approved.
      */
      if (isPurchaseOrderApprovalPending(row)) {
        return "PENDING";
      }

      if (
        Number(row.docstatus || 0) === 1 ||
        status === "completed" ||
        status === "closed" ||
        status === "delivered" ||
        status === "to receive" ||
        status === "to bill" ||
        status === "to receive and bill" ||
        hasAny(["approved", "submitted", "fully approved", "final approved"])
      ) {
        return "APPROVED";
      }

      if (Number(row.docstatus || 0) === 0 || status === "draft" || status === "on hold") {
        return "PENDING";
      }

      return "OTHER";
    }

    if (approvalCurrentActionRequired(kind, row)) return "PENDING";

    if (hasAny([
      "pending", "awaiting", "draft", "open", "not started", "processing",
      "in progress", "review", "verification", "approval required"
    ])) {
      return "PENDING";
    }

    if (hasAny(["approved", "completed", "closed", "submitted", "converted"])) {
      return "APPROVED";
    }

    return "OTHER";
  }

  function approvalTypeMatches(kind, selectedType) {
    selectedType = normalizeApprovalType(selectedType);
    if (selectedType === "ALL") return true;
    if (selectedType === "TRANSFERS") {
      return kind === "c2c" || kind === "p2p" || kind === "b2b";
    }
    return kind.toUpperCase() === selectedType;
  }

  function approvalStageCode(kind, row) {
    row = row || {};

    if (kind === "disc") {
      var level = String(row.approval_level || "").trim().toUpperCase();
      return ["L1", "L2", "L3", "L4"].indexOf(level) >= 0 ? level : "OTHER";
    }

    if (kind === "po") {
      var poState = String(row.workflow_state || "").trim().toLowerCase();
      return poState === "pending ops approval" ? "OPS" : "OTHER";
    }

    var combined = [
      row.workflow_state,
      row.approval_stage,
      row.approval_display_status,
      row.final_approval_status,
      row.conversion_status,
      row.automation_status,
      row.audit_status,
      row.status
    ].map(function (value) {
      return String(value || "").trim().toLowerCase();
    }).join(" ");

    if (
      combined.indexOf("coo") >= 0 ||
      combined.indexOf("operations coo") >= 0 ||
      combined.indexOf("management approval pending") >= 0 ||
      approvalCurrentActionRequired(kind, row)
    ) {
      return "COO";
    }

    if (combined.indexOf("audit") >= 0) return "AUDIT";

    if (
      combined.indexOf("centre manager") >= 0 ||
      combined.indexOf("center manager") >= 0 ||
      combined.indexOf("branch manager") >= 0 ||
      combined.indexOf("manager approval pending") >= 0 ||
      combined.indexOf("cm approval") >= 0
    ) {
      return "CM";
    }

    return "OTHER";
  }

  function approvalStageMatches(kind, row, selectedStage) {
    selectedStage = normalizeApprovalStage(selectedStage);
    if (selectedStage === "ALL") return true;
    return approvalStageCode(kind, row) === selectedStage;
  }

  function approvalStateMatches(kind, row, selectedState) {
    selectedState = normalizeApprovalState(selectedState);
    if (selectedState === "ALL") return true;
    if (selectedState === "CURRENT") {
      return approvalCurrentActionRequired(kind, row);
    }
    return approvalStateCategory(kind, row) === selectedState;
  }

  function approvalStatePillClass(kind, row) {
    var category = approvalStateCategory(kind, row);
    if (category === "APPROVED") return "p-g";
    if (category === "REJECTED") return "p-r";
    if (category === "PENDING") return "p-a";
    return "p-b";
  }

  function currentC2cRows() {
    return c2cRows().filter(function (row) {
      return approvalCurrentActionRequired("c2c", row);
    });
  }

  function currentP2pRows() {
    return p2pRows().filter(function (row) {
      return approvalCurrentActionRequired("p2p", row);
    });
  }

  function approvalViewMatches(kind, row, selectedView) {
    selectedView = normalizeApprovalView(selectedView);

    if (selectedView === "ALL") return true;
    if (selectedView === "COO_PENDING") {
      return approvalCurrentActionRequired(kind, row);
    }
    if (selectedView === "ALL_PENDING") {
      return approvalStateCategory(kind, row) === "PENDING";
    }
    if (selectedView === "APPROVED") {
      return approvalStateCategory(kind, row) === "APPROVED";
    }
    if (selectedView === "REJECTED") {
      return approvalStateCategory(kind, row) === "REJECTED";
    }

    if (/^DISC_L[1-4]_PENDING$/.test(selectedView)) {
      return kind === "disc" &&
        approvalStateCategory(kind, row) === "PENDING" &&
        approvalStageCode(kind, row) === selectedView.replace("DISC_", "").replace("_PENDING", "");
    }

    if (selectedView === "PO_OPS_PENDING") {
      return kind === "po" &&
        approvalStateCategory(kind, row) === "PENDING" &&
        approvalStageCode(kind, row) === "OPS";
    }

    if (selectedView === "TRANSFER_CM_PENDING" ||
        selectedView === "TRANSFER_AUDIT_PENDING" ||
        selectedView === "TRANSFER_COO_PENDING") {
      if (kind !== "c2c" && kind !== "p2p" && kind !== "b2b") return false;
      var wantedStage = selectedView.replace("TRANSFER_", "").replace("_PENDING", "");
      return approvalStateCategory(kind, row) === "PENDING" &&
        approvalStageCode(kind, row) === wantedStage;
    }

    return false;
  }

  function approvalDisplayRows() {
    var range = appointmentPageRange("approvals");
    var selectedView = normalizeApprovalView(range.approvalView || "COO_PENDING");

    function selected(kind, rows) {
      return rows.filter(function (row) {
        return approvalViewMatches(kind, row, selectedView);
      });
    }

    return {
      view: selectedView,
      state: selectedView,
      label: approvalViewLabel(selectedView),
      disc: selected("disc", apprRows()),
      po: selected("po", allPurchaseOrderRows()),
      c2c: selected("c2c", c2cRows()),
      p2p: selected("p2p", p2pRows()),
      b2b: selected("b2b", b2bRows())
    };
  }

  /*
    V30: The main My Approvals tile uses the same strict COO-pending rule as
    the popup. Branch Manager, Audit, ordinary Draft PO, and other intermediate
    stages are intentionally excluded.
  */
  function allApprovals() {
    return {
      disc: apprRows().filter(function (row) {
        return approvalCurrentActionRequired("disc", row);
      }),
      po: allPurchaseOrderRows().filter(function (row) {
        return approvalCurrentActionRequired("po", row);
      }),
      c2c: c2cRows().filter(function (row) {
        return approvalCurrentActionRequired("c2c", row);
      }),
      p2p: p2pRows().filter(function (row) {
        return approvalCurrentActionRequired("p2p", row);
      }),
      b2b: b2bRows().filter(function (row) {
        return approvalCurrentActionRequired("b2b", row);
      })
    };
  }

  /*
   * Loan / finance payment-mode detection used by the target achievement.
   * It covers the payment names already used in the LIFE Clinics setup,
   * including Bajaj, Carepay, Fibe, ShopSE, Savein, Sai Roshini and Liqui.
   */
  function isLoanMode(mode) {
    var value = String(mode || "").trim().toLowerCase();
    if (!value) return false;

    return [
      "loan",
      "finance",
      "shopse",
      "carepay",
      "savein",
      "fibe",
      "bajaj",
      "roshini",
      "liqui",
      "card charges"
    ].some(function (token) {
      return value.indexOf(token) >= 0;
    });
  }

  /*
   * Calculate the amount that contributes to target achievement.
   *
   * Normal payment:
   *   net = gross × 100 ÷ 105
   *
   * Loan / finance payment:
   *   after_15 = gross - (gross × 15%)
   *   five_cut = after_15 × 5%
   *   final_net = after_15 - five_cut
   *
   * Example: ₹1,00,000 loan payment
   *   15% cut  = ₹15,000
   *   balance  = ₹85,000
   *   5% cut   = ₹4,250
   *   achieved = ₹80,750
   */
  function targetPaymentCalculation(row) {
    var gross = parseFloat(row && row.paid_amount) || 0;
    var loan = isLoanMode(row && row.mode_of_payment);

    if (loan) {
      var loanCut = gross * 0.15;
      var afterLoanCut = gross - loanCut;
      var fivePercentCut = afterLoanCut * 0.05;
      var finalNet = afterLoanCut - fivePercentCut;

      return {
        gross: gross,
        loan: true,
        loan_cut: loanCut,
        five_percent_cut: fivePercentCut,
        net: finalNet
      };
    }

    var normalNet = removeGST5(gross);
    return {
      gross: gross,
      loan: false,
      loan_cut: 0,
      five_percent_cut: gross - normalNet,
      net: normalNet
    };
  }

  /*
   * Build branch-wise achievement from submitted Receive Payment Entries.
   * Payment Entries are already loaded with:
   *   docstatus = 1
   *   payment_type = Receive
   *   posting_date inside the selected dashboard range
   */
  function targetSourceForContext() {
    var local = state.pageData && state.pageData.targets;
    if (renderContextTile === "targets" && local && Object.prototype.hasOwnProperty.call(local, "target")) {
      return local.target;
    }
    return state.tgt;
  }

  function targetPaymentsForContext() {
    var local = state.pageData && state.pageData.targets;
    if (renderContextTile === "targets" && local && Array.isArray(local.payments)) {
      return local.payments;
    }
    return state.pe || [];
  }

  function targetPaymentByBranch(sourceRows) {
    var map = {};

    (sourceRows || state.pe || []).forEach(function (r) {
      var branch = String(r.branch || "Unassigned").trim() || "Unassigned";
      if (!map[branch]) {
        map[branch] = {
          branch: branch,
          gross_amount: 0,
          normal_gross_amount: 0,
          loan_gross_amount: 0,
          loan_processing_cut: 0,
          five_percent_cut: 0,
          net_amount: 0,
          payment_count: 0,
          loan_payment_count: 0
        };
      }

      var calc = targetPaymentCalculation(r);
      map[branch].gross_amount += calc.gross;
      map[branch].net_amount += calc.net;
      map[branch].loan_processing_cut += calc.loan_cut;
      map[branch].five_percent_cut += calc.five_percent_cut;
      map[branch].payment_count += 1;

      if (calc.loan) {
        map[branch].loan_gross_amount += calc.gross;
        map[branch].loan_payment_count += 1;
      } else {
        map[branch].normal_gross_amount += calc.gross;
      }
    });

    return map;
  }

  function inclusiveRangeDays(fromDate, toDate) {
    var a = new Date(String(fromDate || "") + "T00:00:00");
    var b = new Date(String(toDate || "") + "T00:00:00");
    if (isNaN(a.getTime()) || isNaN(b.getTime()) || b < a) return 1;
    return Math.floor((b.getTime() - a.getTime()) / 86400000) + 1;
  }

  /* Target rows enriched with live Payment Entry achievement. */
  function targetRowsCalculated() {
    var d = targetSourceForContext();
    if (!d || !d.week_target_vs_archive_details) return [];

    var paymentMap = targetPaymentByBranch(targetPaymentsForContext());
    var days = inclusiveRangeDays(d.from_date || rangeFrom(), d.to_date || rangeTo());

    return d.week_target_vs_archive_details.map(function (source) {
      var branch = String(source.branch || "Unassigned").trim() || "Unassigned";
      var pay = paymentMap[branch] || {
        gross_amount: 0,
        normal_gross_amount: 0,
        loan_gross_amount: 0,
        loan_processing_cut: 0,
        five_percent_cut: 0,
        net_amount: 0,
        payment_count: 0,
        loan_payment_count: 0
      };
      var target = parseFloat(source.targeted_amount) || 0;
      var achieved = parseFloat(pay.net_amount) || 0;

      return {
        branch: branch,
        targeted_amount: target,
        achievement_amount: achieved,
        gross_payment_amount: parseFloat(pay.gross_amount) || 0,
        normal_gross_amount: parseFloat(pay.normal_gross_amount) || 0,
        loan_gross_amount: parseFloat(pay.loan_gross_amount) || 0,
        loan_processing_cut_amount: parseFloat(pay.loan_processing_cut) || 0,
        five_percent_cut_amount: parseFloat(pay.five_percent_cut) || 0,
        payment_entry_count: parseInt(pay.payment_count) || 0,
        loan_payment_count: parseInt(pay.loan_payment_count) || 0,
        deficit: Math.max(target - achieved, 0),
        surplus: Math.max(achieved - target, 0),
        achievement_percentage: target ? (achieved / target) * 100 : 0,
        avg_per_day_achievement: days ? achieved / days : achieved
      };
    });
  }

  /* Target rows for the currently selected dashboard branch. */
  function tgtRows() {
    return targetRowsCalculated().filter(function (r) { return inBr(r.branch); });
  }

  /* Always sum branch rows so target and branch detail remain consistent. */
  function tgtTotals() {
    var rows = tgtRows();
    return {
      target: rows.reduce(function (a, r) {
        return a + (parseFloat(r.targeted_amount) || 0);
      }, 0),
      ach: rows.reduce(function (a, r) {
        return a + (parseFloat(r.achievement_amount) || 0);
      }, 0),
      gross: rows.reduce(function (a, r) {
        return a + (parseFloat(r.gross_payment_amount) || 0);
      }, 0),
      normalGross: rows.reduce(function (a, r) {
        return a + (parseFloat(r.normal_gross_amount) || 0);
      }, 0),
      loanGross: rows.reduce(function (a, r) {
        return a + (parseFloat(r.loan_gross_amount) || 0);
      }, 0),
      loanCut: rows.reduce(function (a, r) {
        return a + (parseFloat(r.loan_processing_cut_amount) || 0);
      }, 0),
      fiveCut: rows.reduce(function (a, r) {
        return a + (parseFloat(r.five_percent_cut_amount) || 0);
      }, 0),
      def: rows.reduce(function (a, r) {
        return a + (parseFloat(r.deficit) || 0);
      }, 0),
      surplus: rows.reduce(function (a, r) {
        return a + (parseFloat(r.surplus) || 0);
      }, 0),
      payments: rows.reduce(function (a, r) {
        return a + (parseInt(r.payment_entry_count) || 0);
      }, 0),
      loanPayments: rows.reduce(function (a, r) {
        return a + (parseInt(r.loan_payment_count) || 0);
      }, 0)
    };
  }
  function paymentEntrySourceRows() {
    var localTile =
      renderContextTile &&
      state.pageData
        ? state.pageData[renderContextTile]
        : null;

    var localRange =
      activeReportRange();

    var rows =
      (
        localTile &&
        Array.isArray(localTile.payments)
      )
        ? localTile.payments
        : (state.pe || []);

    /*
      Sales Summary must always obey its popup From/To range, even when
      ERPNext returns cached or broader Payment Entry rows.
    */
    if (
      localRange &&
      isSalesRangeTile(renderContextTile)
    ) {
      rows = rows.filter(function (row) {
        var postingDate =
          String(
            row.posting_date ||
            row.reference_date ||
            ""
          ).slice(0, 10);

        return (
          postingDate &&
          postingDate >= localRange.from &&
          postingDate <= localRange.to
        );
      });
    }

    return rows;
  }

  function peRows() {
    return paymentEntrySourceRows().filter(function (r) {
      var branch = effectiveBranch();
      return validClinicBranch(r.branch) && (branch === "ALL" || r.branch === branch);
    });
  }

  function attRows() {
    return attendanceSourceRows().filter(function (r) {
      var emp = employeeRecord(r.employee);
      var branch = effectiveBranch();
      if (!emp || !validHrBranch(emp.branch)) return false;
      if (branch !== "ALL" && emp.branch !== branch) return false;
      if (state.emp !== "ALL" && r.employee_name !== state.emp &&
          (!emp || emp.employee_name !== state.emp)) return false;
      return true;
    });
  }

  /* Latest attendance date inside the selected HR range. HR defaults to Today. */
  function attLatest() {
    var a = attRows();
    if (!a.length) return null;
    var d = a[0].attendance_date;
    for (var i = 1; i < a.length; i++) {
      if (a[i].attendance_date > d) d = a[i].attendance_date;
    }
    return d;
  }

  function attendanceReportDate() {
    if (renderContextTile === "hr") {
      var local = activeReportRange();
      if (local && local.from === local.to) return local.to;
    }
    return attLatest() || (renderContextTile === "hr" ? rangeTo() : null);
  }

  function attendanceRowsForDate(dateValue) {
    if (!dateValue) return [];
    return attRows().filter(function (r) {
      return r.attendance_date === dateValue;
    });
  }

  function attToday() {
    return attendanceRowsForDate(attendanceReportDate());
  }

  function attendanceForEmployee(employeeId, dateValue) {
    var key = String(employeeId || "").trim();
    var dateKey = dateValue || attendanceReportDate();
    var rows = attendanceRowsForDate(dateKey);
    for (var i = 0; i < rows.length; i++) {
      if (String(rows[i].employee || "").trim() === key) return rows[i];
    }
    return null;
  }

  function attendanceDateTimeValue(row, kind) {
    if (!row) return "";
    return kind === "in"
      ? (row.custom_check_in_time || row.in_time || "")
      : (row.custom_check_out_time || row.out_time || "");
  }

  function attendanceClockText(value) {
    var raw = String(value || "").trim();
    if (!raw) return "\u2014";
    raw = raw.replace("T", " ");
    var timePart = raw.indexOf(" ") >= 0 ? raw.split(" ")[1] : raw;
    var match = /^(\d{1,2}):(\d{2})/.exec(timePart);
    if (!match) return raw;
    var hour = Number(match[1]);
    var minute = match[2];
    var suffix = hour >= 12 ? "pm" : "am";
    var displayHour = hour % 12 || 12;
    return pad2(displayHour) + ":" + minute + " " + suffix;
  }

  function attendanceHoursText(row) {
    var hours = parseFloat(row && row.working_hours);
    if (!isNaN(hours) && hours > 0) return hours.toFixed(2) + " hrs";
    var inValue = attendanceDateTimeValue(row, "in");
    var outValue = attendanceDateTimeValue(row, "out");
    if (!inValue || !outValue) return "\u2014";
    var start = new Date(String(inValue).replace(" ", "T"));
    var end = new Date(String(outValue).replace(" ", "T"));
    if (isNaN(start.getTime()) || isNaN(end.getTime()) || end < start) return "\u2014";
    return ((end - start) / 3600000).toFixed(2) + " hrs";
  }

  function attendanceStatusClass(status) {
    status = String(status || "").toLowerCase();
    if (status === "present") return "p-g";
    if (status === "absent") return "p-r";
    if (status === "on leave" || status === "half day") return "p-a";
    return "p-gr";
  }

  function sum(rows, k) {
    return rows.reduce(function (a, r) { return a + (parseFloat(r[k]) || 0); }, 0);
  }

  /*
   * Authoritative sales collection source:
   * submitted Receive Payment Entries in the selected posting-date range.
   * This is the same base used by CHECK SALES BY DATE AND PAY MODE.
   */
  function removeGST5(amount) {
    return (parseFloat(amount) || 0) * 100 / 105;
  }

  function salesCollectedTotal() {
    /*
      Sales Summary is a COLLECTION dashboard. Therefore money always comes
      from submitted Receive Payment Entries. Sales Invoices are used only for
      the invoice count and invoice register.
    */
    return sum(peRows(), "paid_amount");
  }

  /* Final collection using the exact Target vs Achievement formula. */
  function salesNetTotal() {
    return peRows().reduce(function (total, row) {
      return total +
        targetPaymentCalculation(row).net;
    }, 0);
  }

  /* GST / second-stage 5% deduction only. Loan processing stays separate. */
  function salesTaxTotal() {
    return peRows().reduce(function (total, row) {
      return total +
        targetPaymentCalculation(row).five_percent_cut;
    }, 0);
  }

  function salesLoanCutTotal() {
    return peRows().reduce(function (total, row) {
      return total +
        targetPaymentCalculation(row).loan_cut;
    }, 0);
  }

  function salesInvoiceCount() {
    var localInvoices =
      localSalesInvoiceRows();

    if (localInvoices) {
      return localInvoices.length;
    }

    return salesRows().reduce(function (a, r) {
      return a +
        (parseInt(r.invoice_count) || 0);
    }, 0);
  }

  function byBranch() {
    var localInvoices =
      localSalesInvoiceRows();

    if (localInvoices) {
      /*
        Exact popup range:
          - invoice count = submitted Sales Invoice posting date
          - money = submitted Receive Payment Entry posting date
        This matches the main COO Sales Summary business rule.
      */
      var exactMap = {};

      function ensureBranch(branch) {
        branch = String(branch || "Unassigned").trim() || "Unassigned";
        if (!exactMap[branch]) {
          exactMap[branch] = {
            branch: branch,
            paid: 0,
            net: 0,
            tax: 0,
            loan: 0,
            inv: 0
          };
        }
        return exactMap[branch];
      }

      localInvoices.forEach(function (row) {
        ensureBranch(row.branch).inv += 1;
      });

      peRows().forEach(function (row) {
        var target = ensureBranch(row.branch);
        var calc = targetPaymentCalculation(row);
        target.paid += calc.gross;
        target.net += calc.net;
        target.tax += calc.five_percent_cut;
        target.loan += calc.loan_cut;
      });

      return Object.keys(exactMap)
        .map(function (key) {
          return exactMap[key];
        })
        .filter(function (row) {
          return row.paid || row.inv;
        })
        .sort(function (a, b) {
          return b.paid - a.paid;
        });
    }

    var m = {};

    salesRows().forEach(function (r) {
      var branch =
        String(
          r.branch ||
          "Unassigned"
        ).trim() ||
        "Unassigned";

      if (!m[branch]) {
        m[branch] = {
          branch: branch,
          paid: 0,
          net: 0,
          tax: 0,
          inv: 0
        };
      }

      m[branch].inv +=
        parseInt(r.invoice_count) || 0;
    });

    peRows().forEach(function (r) {
      var branch =
        String(
          r.branch ||
          "Unassigned"
        ).trim() ||
        "Unassigned";

      if (!m[branch]) {
        m[branch] = {
          branch: branch,
          paid: 0,
          net: 0,
          tax: 0,
          inv: 0
        };
      }

      m[branch].paid +=
        parseFloat(r.paid_amount) || 0;
    });

    Object.keys(m).forEach(function (branch) {
      m[branch].net =
        removeGST5(m[branch].paid);

      m[branch].tax =
        m[branch].paid -
        m[branch].net;
    });

    return Object.keys(m)
      .map(function (key) {
        return m[key];
      })
      .filter(function (row) {
        return row.paid || row.inv;
      })
      .sort(function (a, b) {
        return b.paid - a.paid;
      });
  }

  function byCategory() {
    var m = {};

    salesRows().forEach(function (r) {
      var c =
        String(r.category || "\u2014")
          .replace(/ - LSACPL$/, "");

      if (!m[c]) {
        m[c] = {
          cat: c,
          paid: 0,
          inv: 0
        };
      }

      m[c].paid +=
        parseFloat(r.paid_amount) || 0;

      m[c].inv +=
        parseInt(r.invoice_count) || 0;
    });

    return Object.keys(m)
      .map(function (key) {
        return m[key];
      })
      .sort(function (a, b) {
        return b.paid - a.paid;
      });
  }

  function bySource() {
    var m = {};
    ccRows().forEach(function (r) {
      var s = r.lead_source || "Unknown";
      if (!m[s]) m[s] = { src: s, n: 0, paid: 0 };
      m[s].n++; m[s].paid += parseFloat(r.paid_amount) || 0;
    });
    return Object.keys(m).map(function (k) { return m[k]; })
      .sort(function (a, b) { return b.paid - a.paid; });
  }

  function byAgent() {
    var m = {};
    ccRows().forEach(function (r) {
      var a = (r.cc_agent || "").trim() || "Unassigned";
      if (!m[a]) m[a] = { agent: a, n: 0, paid: 0, out: 0 };
      m[a].n++;
      m[a].paid += parseFloat(r.paid_amount) || 0;
      m[a].out += parseFloat(r.outstanding_amount) || 0;
    });
    return Object.keys(m).map(function (k) { return m[k]; })
      .sort(function (a, b) { return b.paid - a.paid; });
  }

  /* ---------- tiles ---------- */
  var ICO = { sales:"\u25EC", callcentre:"\u260E", branches:"\u2302",
              grievance:"\u26A0", approvals:"\u2713", appointments:"\u25F7",
              service:"\u2295", stock:"\u25A4", hr:"\u265F", tasks:"\u2263",
              tickets:"\u2709", assets:"\u25C8", accounts:"\u20B9", targets:"\u25CE",
              clientinfo:"👥",
              collections:"\u25C9", sources:"\u25F4", agents:"\u263B", outstanding:"\u25D1" };
  var TILE_KEYS = ["approvals","grievance","sales","targets","appointments","service","callcentre",
                   "stock","tasks","tickets","assets","accounts","branches","hr","clientinfo"];

  function tile(key, name, big, sub, stats, extra, badge) {
    var el = $('[data-tile="' + key + '"]');
    if (!el) return;
    var st = (stats || []).map(function (s) {
      return '<div class="t-st"><b class="' + (s.c || "") + '">' + s.v + "</b><span>" + s.l + "</span></div>";
    }).join("");
    el.innerHTML =
      '<div class="t-hd"><div class="t-ico">' + ICO[key] + '</div>' +
      '<div class="t-nm">' + name + "</div>" +
      (badge ? '<span class="badge">' + badge + "</span>" : "") + "</div>" +
      '<div class="t-big">' + big + "</div>" +
      '<div class="t-sub">' + sub + "</div>" +
      '<div class="t-range">' + esc(rangeFooter(key)) + "</div>" +
      (extra || "") +
      (st ? '<div class="t-stats">' + st + "</div>" : "");
  }

  function skeleton() {
    TILE_KEYS.forEach(function (k) {
      var el = $('[data-tile="' + k + '"]');
      if (el) el.innerHTML =
        '<div class="t-hd"><div class="t-ico">' + ICO[k] + '</div><div class="t-nm sk">Loading</div></div>' +
        '<div class="t-big sk">\u2014\u2014\u2014</div><div class="t-sub sk">loading</div>';
    });
    $("[data-strip]").innerHTML = "";
  }

  function render() {
    if (state.loading) { skeleton(); return; }

    var sr = salesRows(), cr = ccRows(), gr = grvRows();
    var paid = salesCollectedTotal();
    var noTax = salesNetTotal();
    var tax = salesTaxTotal();
    var loanCut = salesLoanCutTotal();
    var inv = salesInvoiceCount();
    var ccPaid = sum(cr, "paid_amount");
    var ccOut = sum(cr, "outstanding_amount");
    var ccGT = sum(cr, "grand_total");
    var conv = cr.filter(function (r) { return r.lead_status === "Converted"; }).length;
    var esc_ = gr.filter(function (r) { return r.status === "Escalated"; }).length;
    var red = gr.filter(function (r) { return r.priority === "Red"; }).length;

    /* strip */
    $("[data-strip]").innerHTML = [
      { l: "Collections (Gross)", v: inrS(paid) },
      { l: "Final net", v: inrS(noTax) },
      { l: "Loan processing", v: inrS(loanCut) },
      { l: "GST / 5% cut", v: inrS(tax) },
      { l: "Invoices", v: inv },
      { l: "CC collections", v: inrS(ccPaid) },
      { l: "CC outstanding", v: inrS(ccOut) },
      { l: "Appointments", v: apptRows().length },
      { l: "Pending approvals", v: pendingApprRows().length },
      { l: "Open grievances", v: gr.length },
      { l: "Low stock", v: stockRows().length },
      { l: "Open tasks", v: todoRows().length }
    ].map(function (s) {
      return '<div class="sp"><b>' + s.v + "</b><span>" + s.l + "</span></div>";
    }).join("");

    var cats = byCategory(), brs = byBranch();
    var top = brs[0];

    tile("sales", "Sales Summary", inrS(paid),
      inv + " invoices \u00B7 " + (state.branch === "ALL" ? "all 11 branches" : state.branch),
      [{ v: inrS(noTax), l: "final net" },
       { v: inrS(loanCut), l: "loan processing" },
       { v: inrS(tax), l: "GST / 5%" },
       { v: brs.length, l: "branches" }]);

    tile("callcentre", "Call centre", inrS(ccPaid),
      cr.length + " CC invoices \u00B7 " + conv + " converted",
      [{ v: inrS(ccGT), l: "billed" }, { v: inrS(ccOut), l: "outstanding" },
       { v: pct(ccPaid, ccGT) + "%", l: "realised" }]);

    tile("branches", "Branch ranking", top ? esc(top.branch) : "\u2014",
      top ? inrS(top.paid) + " \u00B7 leader" : "no data",
      [{ v: brs.length, l: "reporting" },
       { v: inrS(brs.length ? paid / brs.length : 0), l: "avg" }],
      top ? bar(100) : "");

    tile("grievance", "Grievances", String(gr.length),
      esc_ + " escalated \u00B7 " + red + " red priority",
      [{ v: esc_, l: "escalated", c: esc_ ? "r" : "" },
       { v: red, l: "red", c: red ? "r" : "" },
       { v: gr.length - esc_, l: "open" }], "", esc_ || 0);

    var AA = allApprovals();
    var totAppr = AA.disc.length + AA.po.length + AA.c2c.length + AA.p2p.length + AA.b2b.length;
    var apVal = AA.disc.reduce(function (a, r) { return a + (parseFloat(r.bill_total) || 0); }, 0);
    var poVal = AA.po.reduce(function (a, r) {
      return a + documentCompanyAmount(r);
    }, 0);
    tile("approvals", "My Approvals", String(totAppr),
      totAppr ? inrS(apVal + poVal) + " + package/branch transfers pending" : "nothing pending",
      [{ v: AA.disc.length, l: "discounts", c: AA.disc.length ? "a" : "" },
       { v: AA.po.length, l: "purchase orders", c: AA.po.length ? "a" : "" },
       { v: AA.c2c.length, l: "C2C", c: AA.c2c.length ? "a" : "" },
       { v: AA.p2p.length, l: "P2P", c: AA.p2p.length ? "a" : "" },
       { v: AA.b2b.length, l: "B2B", c: AA.b2b.length ? "a" : "" }],
      "", totAppr || 0);

    /* appointments */
    var apt = apptRows();
    var seen = apt.filter(isAppointmentCompleted).length;
    var inCl = apt.filter(isAppointmentCheckedIn).length;
    var noSh = apt.filter(isAppointmentNoShow).length;
    var canc = apt.filter(isAppointmentCancelled).length;
    tile("appointments", "Appointments", String(apt.length),
