       { v: canc, l: "cancelled", c: canc ? "a" : "" }],
      apt.length ? bar(pct(seen, apt.length)) : "");

    /* Service Report: booked appointments versus actual Therapy Session executions. */
    var svc = serviceSummary(false);
    tile("service", "Service Report",
      svc.done + " <small>/ " + svc.booked + "</small>",
      "Executed booked appointments \u00B7 rate " + svc.utilisation + "%",
      [{ v: svc.pending, l: "not executed", c: svc.pending ? "a" : "" },
       { v: svc.noShow, l: "no-show", c: svc.noShow ? "r" : "" },
       { v: svc.utilisation + "%", l: "execution rate" }],
      svc.booked ? bar(svc.utilisation, svc.utilisation < 70 ? "a" : "") : "");

    /* stock */
    var stk = stockRows();
    var zero = stk.filter(function (r) { return (parseFloat(r.actual_qty) || 0) <= 0; }).length;
    tile("stock", "Low stock", String(stk.length),
      zero + " items at zero qty",
      [{ v: zero, l: "zero", c: zero ? "r" : "" },
       { v: stk.length - zero, l: "low", c: "a" }],
