    /* hr */
    var emp = hrRows();
    var joins = emp.filter(function (r) {
      return r.date_of_joining && r.date_of_joining >= rangeFrom() && r.date_of_joining <= rangeTo();
    }).length;
    var fem = emp.filter(function (r) { return r.gender === "Female"; }).length;
    var at = attToday();
    var pres = at.filter(function (r) { return r.status === "Present"; }).length;
    var attDate = attLatest();
    tile("hr", "HR", pres ? pres + " <small>/ " + at.length + "</small>" : String(emp.length),
      pres ? "Present on " + attDate + " \u00B7 " + pct(pres, at.length) + "% \u00B7 " +
             emp.length + " active" : emp.length + " active employees",
      [{ v: joins, l: "new joins", c: "g" }, { v: fem, l: "female" },
       { v: emp.length - fem, l: "male" },
       { v: at.filter(function (r) { return r.status === "Absent"; }).length,
         l: "absent", c: "r" }]);

    /* targets: target from target DocType; PE achievement uses normal GST and loan deductions */
    var tg = tgtRows();
    if (tg.length) {
      var TT = tgtTotals();
      var tTot = TT.target, tAch = TT.ach, tDef = TT.def;
      var tPc = pct(tAch, tTot);
      var over = tg.filter(function (r) {
        return (parseFloat(r.achievement_percentage) || 0) >= 100;
      }).length;
      var risk = tg.filter(function (r) {
        return (parseFloat(r.achievement_percentage) || 0) < 70;
      }).length;

      tile("targets", "Target vs Achievement", tPc + "%",
        inrS(tAch) + " net achieved of " + inrS(tTot) +
        " \u00B7 Payment Entry",
        [{ v: over, l: "on target", c: "g" },
         { v: risk, l: "at risk", c: risk ? "r" : "" },
         { v: inrS(tDef), l: "deficit", c: tDef > 0 ? "a" : "" }],
        bar(tPc, tPc >= 90 ? "" : tPc >= 70 ? "a" : "r"),
        risk || 0);
    } else {
      tile("targets", "Target vs Achievement", "\u2014",
        state.err.tgt ? "Target data unavailable" : "No target period overlaps the selected range",
        [{ v: "\u2014", l: "set a target" }]);
