    /* tickets — LIFE Ticket / Helpdesk dashboard */
    var tk = tickRows();
    var tkOpen = tk.filter(function (r) {
      return ["Open", "Reopened", "Replied", "On Hold"].indexOf(ticketStatus(r)) >= 0;
    });
    var tkHi = tkOpen.filter(function (r) {
      return String(r.priority || "").toLowerCase() === "high";
    }).length;
    var tkResolved = tk.filter(function (r) { return ticketStatus(r) === "Resolved"; }).length;
    var tkSlaFailed = tk.filter(function (r) { return r.agreement_status === "Failed"; }).length;

    tile("tickets", "Tickets", String(tkOpen.length) + " <small>Active</small>",
      tk.length + " total \u00B7 Task Manager & Ticket System",
      [{ v: tkHi, l: "high", c: tkHi ? "r" : "" },
       { v: tkResolved, l: "resolved", c: "g" },
       { v: tkSlaFailed, l: "sla failed", c: tkSlaFailed ? "r" : "" }],
      "", (tkHi + tkSlaFailed) || 0);


    /* accounts */
    var pes = peRows();
    var peTot = pes.reduce(function (a, r) { return a + (parseFloat(r.paid_amount) || 0); }, 0);
    var mop = {};
    pes.forEach(function (r) {
      var m = r.mode_of_payment || "Unspecified";
      mop[m] = (mop[m] || 0) + (parseFloat(r.paid_amount) || 0);
    });
    var mopL = Object.keys(mop).map(function (k) { return { n: k, v: mop[k] }; })
      .sort(function (a, b) { return b.v - a.v; });
    var cash = mop["Cash"] || 0;
    var peFinalNet = pes.reduce(function (a, r) {
      return a + targetPaymentCalculation(r).net;
    }, 0);
    var peLoanCut = pes.reduce(function (a, r) {
      return a + targetPaymentCalculation(r).loan_cut;
    }, 0);
    var peFiveCut = pes.reduce(function (a, r) {
      return a + targetPaymentCalculation(r).five_percent_cut;
    }, 0);
    tile("accounts", "Accounts", inrS(peTot),
      "Gross collections \u00B7 final net " + inrS(peFinalNet),
      [{ v: inrS(peLoanCut), l: "loan processing" },
       { v: inrS(peFiveCut), l: "GST / 5%" },
       { v: inrS(ccOut), l: "cc outstanding" },
       { v: mopL.length, l: "modes" }]);

    tile(
      "clientinfo",
      "Client Info",
      "Open",
      "Complete Clients & Service Dashboard",
      [
        { v: "Search", l: "clients", c: "g" },
        { v: "Profiles", l: "full details" },
        { v: "Invoices", l: "plans & sessions" }
