  function ticketPriorityClass(priority) {
    var value = String(priority || "").toLowerCase();
    if (value === "high" || value === "urgent") return "p-r";
    if (value === "medium") return "p-a";
    if (value === "low") return "p-b";
    return "p-gr";
  }

  function durationText(value) {
    var seconds = Number(value);
    if (!isFinite(seconds) || seconds < 0) return value ? esc(value) : "\u2014";
    seconds = Math.round(seconds);
    var days = Math.floor(seconds / 86400);
    var hours = Math.floor((seconds % 86400) / 3600);
    var mins = Math.floor((seconds % 3600) / 60);
    var parts = [];
    if (days) parts.push(days + "d");
    if (hours) parts.push(hours + "h");
    if (mins || !parts.length) parts.push(mins + "m");
    return parts.join(" ");
  }

  function ticketOpenedText(r) {
    var date = (r && r.opening_date) || "\u2014";
