    if (value === "Completed" || value === "Closed" || value === "Resolved") return "p-g";
    if (value === "Cancelled") return "p-gr";
    if (value === "Overdue") return "p-r";
    if (value === "Reopened" || value === "Replied") return "p-b";
    if (value === "On Hold") return "p-gr";
