  function currentTicketUser() {
    return String(
      (window.frappe && frappe.session && frappe.session.user) || ""
    ).trim();
  }

  function normaliseTicketIdentity(value) {
    return String(value || "").trim().toLowerCase();
  }

  function currentTicketIdentityMap() {
    var map = {};
    function add(value) {
      value = normaliseTicketIdentity(value);
      if (value) map[value] = true;
    }

    var user = currentTicketUser();
    add(user);

    var employee = employeeRecord(user);
    if (employee) {
      add(employee.name);
      add(employee.employee_name);
      add(employee.user_id);
      add(employee.company_email);
      add(employee.personal_email);
      add(employee.prefered_email);
    }

    return map;
  }

  function ticketIdentityMatchesCurrentUser(value) {
    var identities = currentTicketIdentityMap();
    var raw = normaliseTicketIdentity(value);
    if (!raw) return false;
    if (identities[raw]) return true;

    var employee = employeeRecord(value);
    if (!employee) return false;

    return [
      employee.name,
      employee.employee_name,
      employee.user_id,
      employee.company_email,
      employee.personal_email,
      employee.prefered_email
    ].some(function (candidate) {
      return !!identities[normaliseTicketIdentity(candidate)];
    });
  }

  function myTicketGroups(rows) {
    rows = rows || [];

    var taggedToMe = rows.filter(function (row) {
      var info = ticketInfo(row);
      var meta = info.meta || {};
      return ticketIdentityMatchesCurrentUser(meta.tag_to) ||
        (Array.isArray(meta.cc_to) && meta.cc_to.some(ticketIdentityMatchesCurrentUser));
    });

    var raisedByMe = rows.filter(function (row) {
      return ticketIdentityMatchesCurrentUser(row.raised_by) ||
        ticketIdentityMatchesCurrentUser(row.owner);
    });

    return {
      taggedToMe: taggedToMe,
      raisedByMe: raisedByMe
    };
  }

