  function myTicketsDashboardHtml(rows) {
    ensureMyTicketsDashboardStyle();

    var groups = myTicketGroups(rows);
    var combinedNames = {};
    groups.taggedToMe.concat(groups.raisedByMe).forEach(function (row) {
      combinedNames[row.name] = true;
    });
