  function decodeClientInfoEmbeddedBundle() {
    if (
      decodeClientInfoEmbeddedBundle._promise
    ) {
      return decodeClientInfoEmbeddedBundle._promise;
    }

    decodeClientInfoEmbeddedBundle._promise =
      Promise.resolve()
        .then(function () {
          if (
            typeof DecompressionStream !==
            "function"
          ) {
            throw new Error(
              "This browser cannot decode the compressed Client Info dashboard. " +
              "Please use the current Google Chrome browser."
            );
          }

          var binary =
            window.atob(
              CLIENT_INFO_EMBEDDED_GZIP_B64
            );

          var bytes =
            new Uint8Array(
              binary.length
            );

          for (
            var index = 0;
            index < binary.length;
            index += 1
          ) {
            bytes[index] =
              binary.charCodeAt(index);
          }

          var stream =
            new Blob([bytes])
              .stream()
              .pipeThrough(
                new DecompressionStream(
                  "gzip"
                )
              );

          return new Response(
            stream
          ).text();
        })
        .then(function (jsonText) {
          var data =
            JSON.parse(
              jsonText || "{}"
            );

          if (
            !data.html ||
            !data.style ||
            !data.script
          ) {
            throw new Error(
              "The embedded Client Info dashboard bundle is incomplete."
            );
          }

          return data;
        });

    return decodeClientInfoEmbeddedBundle._promise;
  }

