  function taskTicketFindRecordRow(
    scope,
    doctype,
    recordName
  ) {
    if (
      !scope ||
      !recordName ||
      !scope.querySelectorAll
    ) {
      return null;
    }

    var rows =
      scope.querySelectorAll(
        '[data-doctype="' +
        doctype +
        '"][data-docname]'
      );

    for (
      var index = 0;
      index < rows.length;
      index += 1
    ) {
      if (
        String(
          rows[index].getAttribute(
            "data-docname"
          ) || ""
        ) === String(recordName)
      ) {
        return rows[index];
      }
    }

    return null;
  }

