  function focusSelectedTaskTicketRecord(
    host,
    launch
  ) {
    launch = launch || {};

    var moduleName =
      launch.moduleName === "task"
        ? "task"
        : "ticket";

    var recordName =
      moduleName === "task"
        ? String(
            launch.selectedTask || ""
          ).trim()
        : String(
            launch.selectedTicket || ""
          ).trim();

    if (!recordName) return;

    var doctype =
      moduleName === "task"
        ? "ToDo"
        : "Issue";

    var bodySelector =
      moduleName === "task"
        ? "#task-report-body"
        : "#ticket-report-body";

    var pagerSelector =
      moduleName === "task"
        ? "#life-pager-taskReport"
        : "#life-pager-ticketReport";

    var attempts = 0;
    var pageClicks = 0;
    var lastPageClick = 0;
    var maxAttempts = 160;

    function focus() {
      attempts += 1;

      var scope =
        taskTicketRenderScope(host);

      if (!scope) {
        if (attempts < maxAttempts) {
          window.setTimeout(
            focus,
            160
          );
        }

        return;
      }

      /*
        The Task Manager can default to a grouped-by-assignee view.
        A selected task needs the normal list view so its exact row can
        be found across report pagination and placed first.
      */
      if (moduleName === "task") {
        var viewMode =
          scope.querySelector(
            "#tr-view-mode"
          );

        if (
          viewMode &&
          String(viewMode.value || "") !==
            "list"
        ) {
          viewMode.value = "list";

          try {
            viewMode.dispatchEvent(
              new Event(
                "change",
                {
                  bubbles: true
                }
              )
            );
          } catch (ignoreViewModeChange) {}
        }
      }

      var row =
        taskTicketFindRecordRow(
          scope,
          doctype,
          recordName
        );

      if (row) {
        taskTicketHighlightSelectedRow(
          scope,
          moduleName,
          recordName,
          row
        );

        return;
      }

      var body =
        scope.querySelector(
          bodySelector
        );

      var pager =
        scope.querySelector(
          pagerSelector
        );

      var nextButton =
        pager &&
        pager.querySelector(
          'button[data-act="next"]'
        );

      var now = Date.now();

      if (
        body &&
        nextButton &&
        !nextButton.disabled &&
        (
          !lastPageClick ||
          now - lastPageClick >= 500
        )
      ) {
        lastPageClick = now;
        pageClicks += 1;

        try {
          nextButton.click();
        } catch (ignoreNextPageClick) {}
      }

      /*
        Stop after enough time/pages. Normal reports use ten rows per page,
        so 160 attempts safely covers a large result set while still ending.
      */
      if (
        attempts < maxAttempts &&
        pageClicks < 100
      ) {
        window.setTimeout(
          focus,
          180
        );
      }
    }

    window.setTimeout(
      focus,
      450
    );
  }


  function selectRequestedTaskTicketViewAfterLoad(host) {
    var attempts = 0;
    var maxAttempts = 80;
    var launch = requestedTaskTicketLaunch();
    var moduleSelector = launch.moduleName === "task" ? "#toggle-task" : "#toggle-ticket";
    var subIndex = launch.viewName === "report" ? "1" : (launch.viewName === "new" ? "0" : "2");
    var subSelector = launch.moduleName === "task"
      ? '[data-task-sub="' + subIndex + '"]'
      : '[data-ticket-sub="' + subIndex + '"]';

    function select() {
      attempts += 1;
      var scope = taskTicketRenderScope(host);
      var moduleToggle = scope && scope.querySelector ? scope.querySelector(moduleSelector) : null;
      var subTab = scope && scope.querySelector ? scope.querySelector(subSelector) : null;

      if (moduleToggle && subTab) {
        try { moduleToggle.click(); } catch (ignoreModuleToggle) {}
        window.setTimeout(function () {
          try {
            subTab.click();
          } catch (ignoreSubTab) {}

          focusSelectedTaskTicketRecord(
            host,
            launch
          );
        }, 120);
        return;
      }

      if (attempts < maxAttempts) window.setTimeout(select, 150);
    }

    window.setTimeout(select, 120);
  }

