  /*
    Open the embedded TASK MANAGER & TICKET SYSTEM in a dedicated new tab.

    This dashboard already contains the complete Task Manager HTML, CSS and
    JavaScript bundle. Therefore no external Web Page route is required.
    This avoids:
      - website 404 errors,
      - incorrect C2C/B2B/P2P route selection,
      - Web Page permission/route-discovery failures.

    The Task/Ticket tile still opens the COO popup first. Only the popup's
    Open All Tasks Report / Open All Tickets Report button calls this function.
  */
  function openLifeWorkSystem(
    moduleName,
    viewName,
    selectedRecord
  ) {
