      String(
        selectedRecord || ""
      ).trim();

    var moduleLabel =
      moduleName === "task"
        ? "Task Management"
        : "Ticket / Helpdesk";

    var viewLabel =
      viewName === "report"
        ? (
            moduleName === "task"
              ? "All Tasks Report"
              : "All Tickets Report"
          )
        : viewName === "new"
        ? (
            moduleName === "task"
              ? "Assign New Task"
              : "Raise New Ticket"
          )
        : (
            moduleName === "task"
              ? "My Tasks"
              : "My Tickets"
          );

    var targetWindow = window.open(
      "about:blank",
      "_blank"
    );

    if (!targetWindow) {
      toast(
        "Allow pop-ups to open the Task Manager & Ticket System"
      );
      return;
    }

    try {
      targetWindow.opener = null;
    } catch (ignoreOpener) {}

