        '<title>Opening LIFE Task Manager...</title>' +
        '<div style="font:14px Arial;padding:24px">' +
        "Opening TASK MANAGER &amp; TICKET SYSTEM \u2192 " +
        esc(moduleLabel) +
        " \u2192 " +
        esc(viewLabel) +
        "...</div>"
      );
      targetWindow.document.close();
    } catch (ignoreWrite) {}

    var url;

    try {
      /*
        Reuse the current working COO Web Page route. The special standalone
        parameter makes the new tab render only the embedded Task Manager,
        not the COO dashboard.
      */
      url = new URL(window.location.href);
      url.hash = "";
      url.search = "";

      url.searchParams.set(
        TASK_TICKET_STANDALONE_PARAM,
        "1"
      );

      url.searchParams.set(
        "life_module",
        moduleName
      );

      url.searchParams.set(
        "life_view",
        viewName
      );

      url.searchParams.set(
        "coo_view",
        "all_report"
      );

      url.searchParams.set(
        "coo_build",
        "selected_task_first_v3"
      );

      if (selectedRecord) {
        url.searchParams.set(
          moduleName === "task"
            ? "coo_task"
            : "coo_ticket",
          selectedRecord
        );
      }

      url = url.toString();
    } catch (ignoreUrl) {
      url =
        window.location.origin +
        window.location.pathname +
        "?" +
        TASK_TICKET_STANDALONE_PARAM +
        "=1&life_module=" +
        encodeURIComponent(moduleName) +
        "&life_view=" +
        encodeURIComponent(viewName) +
        "&coo_view=all_report" +
        "&coo_build=selected_task_first_v3" +
        (
          selectedRecord
            ? (
                moduleName === "task"
                  ? "&coo_task="
                  : "&coo_ticket="
              ) +
              encodeURIComponent(
                selectedRecord
              )
            : ""
        );
    }

    targetWindow.location.replace(url);
  }

