  function targetModeBreakdownRows() {
    var map = {};
    targetPaymentsForContext().filter(function (row) {
      return inBr(row.branch);
    }).forEach(function (row) {
      var mode = String(row.mode_of_payment || "Unspecified").trim() || "Unspecified";
      if (!map[mode]) {
        map[mode] = { mode: mode, gross: 0, gst: 0, exGst: 0, cut: 0, final: 0, count: 0 };
      }
      var calc = targetPaymentCalculation(row);
      map[mode].gross += calc.gross;
      map[mode].gst += calc.five_percent_cut;
      map[mode].exGst += calc.gross - calc.five_percent_cut;
      map[mode].cut += calc.loan_cut;
      map[mode].final += calc.net;
      map[mode].count += 1;
    });
    return Object.keys(map).map(function (key) { return map[key]; })
      .sort(function (a, b) { return b.final - a.final; });
  }

