  /* navigation stack: each entry {t, arg, label} */
  var nav = [];

  function openModal(t, arg, label) {
    /* Root tile aliases only. Detail views are intentionally NOT normalised,
       because the explicit View button must open the selected ticket/task
       inside the dashboard popup. */
    if (t === "ticket") {
      t = "tickets";
      arg = null;
      label = TITLES.tickets || "Tickets";
    }
    if (t === "task") {
      t = "tasks";
      arg = null;
      label = TITLES.tasks || "Task Management";
    }

    /*
      Every fresh My Approvals opening defaults to COO Pending Records
      across ALL dates. The current dashboard branch is retained, while the
      main COO dashboard dates/cards remain unchanged.
    */
    if (t === "approvals" && !arg) {
      state.pageRanges.approvals = {
        from: state.fromDate || CYC.from,
        to: state.toDate || CYC.to,
        preset: "coo-pending-all-dates",
        branch: state.branch || "ALL",
        approvalView: "COO_PENDING"
      };

      if (state.pageData) {
        delete state.pageData.approvals;
      }

      if (state.err) {
        state.err.approvalsPage = "";
      }
    }

    /*
      Every fresh Service Report opening starts on Today.
      Clear any previously loaded local Service range so the current
      dashboard's Today appointments/sessions and expiry watch are used.
    */
    if (t === "service" && !arg) {
      state.pageRanges.service = {
        from: CYC.today,
        to: CYC.today,
        preset: "today",
        branch: state.branch || "ALL"
      };

      if (state.pageData) {
        delete state.pageData.service;
      }

      if (state.err) {
        state.err.servicePage = "";
      }
    }

    var overlay = $("[data-ovl]");
    var body = $("[data-m-body]");
    if (!t || !overlay || !body) {
      void 0;
      return;
    }

    ensureAppointmentPageRange(t);
    nav = [{ t: t, arg: arg || null, label: label || TITLES[t] || t }];

    /* Open immediately, then render on the next task. This lets the browser
       paint the popup before building any large report table. */
    overlay.classList.add("on");
    overlay.setAttribute("aria-hidden", "false");
    overlay.style.display = "flex";
    overlay.style.position = "fixed";
    overlay.style.inset = "0";
    overlay.style.zIndex = "999999";
    body.scrollTop = 0;

    var title = $("[data-m-title]");
    var sub = $("[data-m-sub]");
    var kp = $("[data-m-kpis]");
    var note = $("[data-m-note]");
    var go = $("[data-go]");
    if (title) {
      title.textContent = (typeof TITLES !== "undefined" && TITLES[t])
        ? TITLES[t]
        : String(t || "Report");
      title.style.color = "#FFFFFF";
    }
    if (sub) sub.textContent = rangeText();
    if (kp) kp.innerHTML = "";
    if (note) note.textContent = "Loading report...";
    if (go) go.hidden = true;
    body.innerHTML = '<div class="empty">Loading report...</div>';

    var token = (openModal._renderToken || 0) + 1;
    openModal._renderToken = token;

    window.setTimeout(function () {
      if (openModal._renderToken !== token || !overlay.classList.contains("on")) return;
      try {
        /*
          My Approvals now opens directly on COO Pending Records (All Dates).
          Load the all-date COO-pending dataset immediately so the user does
          not need to click Apply just to get the default view.
        */
        if (
          t === "approvals" &&
          !arg &&
          state.pageRanges.approvals &&
          state.pageRanges.approvals.preset === "coo-pending-all-dates"
        ) {
          loadApprovalsPageRange(
            state.pageRanges.approvals.from,
            state.pageRanges.approvals.to,
            "coo-pending-all-dates",
            state.pageRanges.approvals.branch || "ALL",
            "COO_PENDING",
            null
          );
          return;
        }

        paint();
      } catch (err) {
        void 0;
        if (title) {
          title.textContent = (typeof TITLES !== "undefined" && TITLES[t])
            ? TITLES[t]
            : String(t || "Report");
          title.style.color = "#FFFFFF";
        }
        if (sub) sub.textContent = rangeText();
        if (kp) kp.innerHTML = "";
        if (note) note.textContent = "The popup opened, but this report has a JavaScript rendering error.";
        if (go) go.hidden = true;
        body.innerHTML =
          '<div class="err"><b>Could not render this report.</b><br>' +
          esc((err && err.message) || String(err || "Unknown error")) +
          '<br><small>Open the browser console for the exact line number.</small></div>';
      }
    }, 20);
  }
  function pushView(t, arg, label) {
    /* Keep the report as the first navigation level and allow explicit
       ticket/task details to become the second level. */
    if (t === "ticket") t = "tickets";
    if (t === "task") t = "tasks";
    nav.push({ t: t, arg: arg || null, label: label || t });
    paint();
  }
  function popView() {
    if (nav.length > 1) { nav.pop(); paint(); }
    else closeModal();
  }
  function closeModal() {
    var overlay = $("[data-ovl]");
    if (overlay) {
      overlay.classList.remove("on");
      overlay.setAttribute("aria-hidden", "true");
      overlay.style.display = "none";
    }
    nav = [];
    openModal._renderToken = (openModal._renderToken || 0) + 1;
  }

  function paint() {
    var cur = nav[nav.length - 1];
    if (!cur) return;
    var root0 = nav[0];
    $("[data-m-ico]").textContent = ICO[root0.t] || "\u25C9";
    var modalRange = appointmentPageRange(root0.t);
    var subFrom = modalRange.from;
    var subTo = modalRange.to;
    var modalBranch = modalRange.branch || "ALL";
    var isTargetRoot = root0.t === "targets" && cur.t === "targets";
    $("[data-m-title]").textContent = isTargetRoot
      ? "Target & Realisation (Range: " + subFrom + " \u2192 " + subTo + ")"
      : cur.label;
    $("[data-m-title]").style.color = "#FFFFFF";
    $("[data-m-sub]").textContent = isTargetRoot
      ? (modalBranch === "ALL" ? "All Branches" : modalBranch) + " \u00B7 Range view (Collections)"
      : formatBusinessDate(subFrom) + " \u2192 " + formatBusinessDate(subTo) +
        (modalBranch === "ALL" ? " \u00B7 all branches" : " \u00B7 " + modalBranch) +
        (root0.t === "approvals"
          ? " \u00B7 " + approvalStateLabel(modalRange.approvalState || "CURRENT")
          : "");
    $("[data-back]").hidden = nav.length < 2;
    var showGo = nav.length === 1 && FULL_OK[root0.t];
    $("[data-go]").hidden = !showGo;
    $("[data-m-note]").textContent = showGo
      ? "Charts, full register and breakdowns"
      : (nav.length > 1 ? "Click any row to drill deeper" : "");
    $("[data-m-kpis]").innerHTML = "";
    $("[data-m-body]").innerHTML = '<div class="empty">Loading\u2026</div>';
    renderContextTile = root0.t;
    try {
      renderModal(cur.t, cur.arg);
    } finally {
      renderContextTile = "";
    }
    prependRangeFilter($("[data-m-body]"), root0.t);
    if (nav.length > 1) {
      var c = document.createElement("div");
      c.className = "crumb";
      c.innerHTML = nav.map(function (n, i) {
        return (i === nav.length - 1 ? "<b>" + esc(n.label) + "</b>" : esc(n.label));
      }).join(" \u203A ");
      var b = $("[data-m-body]");
      b.insertBefore(c, b.firstChild);
    }
  }

