  function workflowAllRequestsLink(
    kind,
    label,
    requestName,
    clientName
  ) {
    kind = String(kind || "").trim().toLowerCase();
    requestName = String(requestName || "").trim();

    /*
      C2C and P2P pages now support exact URL routing themselves. A normal
      target=_blank link is more reliable than the legacy popup scanner that
      repeatedly clicked tabs and searched paginated request cards.
    */
    if (
      kind === "c2c" ||
      kind === "p2p"
    ) {
      var directPath =
        kind === "p2p"
          ? "/package-conversion-for-p2p"
          : "/package-conversion-c2c";

      var directHref =
        directPath +
        "?tab=all" +
        (
          requestName
            ? "&request=" + encodeURIComponent(requestName)
            : ""
        );

      return '<a class="go-lnk" target="_blank" rel="noopener" href="' +
        esc(directHref) + '">' +
        esc(label || "View Request") + " \u2197</a>";
    }

    /* B2B still uses its existing workflow opener. */
    return '<a class="go-lnk" href="#" data-workflow-all="' +
      esc(kind) + '"' +
      (requestName
        ? ' data-workflow-request="' + esc(requestName) + '"'
        : "") +
      (clientName
        ? ' data-workflow-client="' + esc(clientName) + '"'
        : "") +
      '>' + esc(label || "View All Requests") + " \u2197</a>";
  }

  /*
    C2C records shown in the COO Dashboard are already at the final
    Operations COO / Management stage. Open the selected request directly
    in the C2C Approval Dashboard instead of sending it to All Requests.
  */
  function c2cCooApprovalLink(requestName, label) {
    requestName = String(requestName || "").trim();

    if (!requestName) {
      return "\u2014";
    }

    var href =
      "/package-conversion-c2c" +
      "?tab=approval" +
      "&role=coo" +
      "&request=" +
      encodeURIComponent(requestName);

    return '<a class="go-lnk" target="_blank" rel="noopener"' +
      ' data-c2c-coo-approval="1" href="' + esc(href) + '">' +
      esc(label || "Review COO Approval") + " \u2197</a>";
