  function workflowTargetText(value) {
    return String(value || "")
      .replace(/\s+/g, " ")
      .trim()
      .toLowerCase();
  }

  function workflowElementVisible(element) {
    if (!element) return false;

    var style = element.ownerDocument &&
      element.ownerDocument.defaultView &&
      element.ownerDocument.defaultView.getComputedStyle
      ? element.ownerDocument.defaultView.getComputedStyle(element)
      : null;

    if (style && (style.display === "none" || style.visibility === "hidden")) {
      return false;
    }

    return !element.disabled;
  }

  function workflowSelectedBanner(
    doc,
    panel,
    requestName,
    clientName
  ) {
    if (!doc || !panel || (!requestName && !clientName)) return;

    var oldBanner = doc.getElementById("cooSelectedWorkflowRequest");

    if (oldBanner && oldBanner.parentNode !== panel) {
      oldBanner.parentNode.removeChild(oldBanner);
      oldBanner = null;
    }

    var banner = oldBanner || doc.createElement("div");
    banner.id = "cooSelectedWorkflowRequest";

    banner.style.cssText =
      "position:relative;z-index:5;margin:0 0 14px;padding:12px 14px;" +
      "border:2px solid #2E7D32;border-radius:12px;background:#E8F5E9;" +
      "color:#0F3D1E;font-family:Arial,sans-serif;box-shadow:0 4px 14px " +
      "rgba(46,125,50,.16)";

    banner.innerHTML =
      '<div style="font-size:10px;font-weight:800;letter-spacing:.7px;' +
      'text-transform:uppercase;color:#2E7D32;margin-bottom:4px">' +
      "Selected from COO Dashboard</div>" +
      '<div style="font-size:15px;font-weight:900">' +
      esc(clientName || "Selected Client") +
      "</div>" +
      (requestName
        ? '<div style="font-size:11px;font-weight:700;color:#52705A;' +
          'margin-top:3px">Request: ' + esc(requestName) + "</div>"
        : "");

    if (!oldBanner) {
      panel.insertBefore(banner, panel.firstChild);
    }
  }

  function workflowCandidateContainer(node) {
    if (!node || !node.closest) return node;

    return node.closest(
      "tr," +
      ".pkg-request-item," +
      ".b2b-request-item," +
      ".b2b-request-card," +
      ".c2c-request-item," +
      ".c2c-request-card," +
      ".request-item," +
      ".request-card," +
      ".list-group-item," +
      "[data-docname]," +
      "[data-request-name]," +
      "[data-request]"
    ) || node;
  }

  function workflowFindTarget(
    panel,
    requestName,
    clientName
  ) {
    if (!panel) return null;

    var requestKey = workflowTargetText(requestName);
    var clientKey = workflowTargetText(clientName);

    var selectors = [
      ".pkg-request-item",
      "tbody tr",
      ".b2b-request-item",
      ".b2b-request-card",
      ".c2c-request-item",
      ".c2c-request-card",
      ".request-item",
      ".request-card",
      ".list-group-item",
      "[data-docname]",
      "[data-request-name]",
      "[data-request]"
    ].join(",");

    var nodes = Array.prototype.slice.call(
      panel.querySelectorAll(selectors)
    );

    function nodeDataText(node) {
      if (!node) return "";

      var values = [
        node.getAttribute && node.getAttribute("data-docname"),
        node.getAttribute && node.getAttribute("data-request-name"),
        node.getAttribute && node.getAttribute("data-request"),
        node.getAttribute && node.getAttribute("data-doc"),
        node.dataset && node.dataset.docname,
        node.dataset && node.dataset.requestName,
        node.dataset && node.dataset.request
      ];

      return workflowTargetText(values.filter(function (value) {
        return !!value;
      }).join(" "));
    }

    var exactRequestNode = null;
    var textRequestNode = null;
    var clientNode = null;

    nodes.some(function (rawNode) {
      var node = workflowCandidateContainer(rawNode);
      if (!node || node.id === "cooSelectedWorkflowRequest") return false;

      var dataText = nodeDataText(node);
      var fullText = workflowTargetText(node.textContent || "");

      if (
        requestKey &&
        (
          dataText === requestKey ||
          dataText.indexOf(requestKey) >= 0
        )
      ) {
        exactRequestNode = node;
        return true;
      }

      if (
        requestKey &&
        !textRequestNode &&
        fullText.indexOf(requestKey) >= 0
      ) {
        textRequestNode = node;
      }

      if (
        clientKey &&
        !clientNode &&
        fullText.indexOf(clientKey) >= 0
      ) {
        clientNode = node;
      }

      return false;
    });

    return exactRequestNode || textRequestNode || clientNode;
  }

  function workflowNextPageButton(panel, kind) {
    if (!panel) return null;

    var knownSelectors = kind === "p2p"
      ? [
          "#pkgNextPageBtn",
          "#pkgRequestNextPage",
          "[data-page-next]"
        ]
      : kind === "b2b"
      ? [
          "#b2bNextPage",
          "#b2b-next-page",
          "#b2bNextBtn",
          "[data-b2b-next]",
          "[data-page-next]"
        ]
      : [
          "#c2cNextPage",
          "#c2c-next-page",
          "#nextPageBtn",
          "#next-page",
          "[data-c2c-next]",
          "[data-page-next]"
        ];

    var i;
    var button;

    for (i = 0; i < knownSelectors.length; i += 1) {
      button = panel.querySelector(knownSelectors[i]);

      if (button && workflowElementVisible(button)) {
        return button;
      }
    }

    var pagingButtons = panel.querySelectorAll(
      '[class*="pagination"] button,' +
      '[class*="pagination"] a,' +
      '[id*="pagination"] button,' +
      '[id*="pagination"] a,' +
      '[class*="pager"] button,' +
      '[class*="pager"] a'
    );

    for (i = 0; i < pagingButtons.length; i += 1) {
      button = pagingButtons[i];

      var buttonText = workflowTargetText(
        button.textContent ||
        button.getAttribute("aria-label") ||
        button.getAttribute("title") ||
        ""
      );

      if (
        workflowElementVisible(button) &&
        (
          buttonText === "next" ||
          buttonText.indexOf("next") >= 0 ||
          buttonText === "\u203a" ||
          buttonText === "\u00bb"
        )
      ) {
        return button;
      }
    }

    return null;
  }

  function workflowFocusSelectedRequest(
    popup,
    config,
    kind,
    requestName,
    clientName,
    focusState
  ) {
    if (!popup || !popup.document || (!requestName && !clientName)) {
      return true;
    }

    var doc = popup.document;
    var panel = config.panelId
      ? doc.getElementById(config.panelId)
      : doc.body;

    if (!panel) return false;

    workflowSelectedBanner(
      doc,
      panel,
      requestName,
      clientName
    );

    var target = workflowFindTarget(
      panel,
      requestName,
      clientName
    );

    if (target) {
      var parent = target.parentNode;

      /*
        Move only the selected request row/card to the top of its current
        request list. The original request remains fully clickable.
      */
      if (
        parent &&
        parent.firstElementChild &&
        parent.firstElementChild !== target
      ) {
        parent.insertBefore(target, parent.firstElementChild);
      }

      target.setAttribute("data-coo-selected-request", "1");
      target.style.outline = "3px solid #2E7D32";
      target.style.outlineOffset = "-2px";
      target.style.backgroundColor = "#F1F8F2";
      target.style.boxShadow = "0 5px 18px rgba(46,125,50,.22)";

      try {
        target.scrollIntoView({
          behavior: "smooth",
          block: "start"
        });
      } catch (scrollError) {
        target.scrollIntoView(true);
      }

      window.setTimeout(function () {
        try {
          target.click();

          /*
            Some registers bind the action to a View/Open button inside
            the row instead of binding the complete row.
          */
          var innerAction = target.querySelector(
            'button[class*="view"],' +
            'button[class*="open"],' +
            'a[class*="view"],' +
            'a[class*="open"],' +
            '[data-view-request],' +
            '[data-open-request]'
          );

          if (innerAction && workflowElementVisible(innerAction)) {
            innerAction.click();
          }
        } catch (clickError) {
          void 0;
        }
      }, 100);

      return true;
    }

    /*
      P2P, C2C and B2B lists may be paginated. Move through the pages
      until the exact request clicked in the COO dashboard is found.
    */
    var now = Date.now();

    if (
      !focusState.lastNextClick ||
      now - focusState.lastNextClick >= 500
    ) {
      var nextButton = workflowNextPageButton(panel, kind);

      if (nextButton) {
        focusState.lastNextClick = now;
        focusState.pagesChecked += 1;
        nextButton.click();
      }
    }

    return false;
  }

  function openWorkflowAllRequests(
    kind,
    requestName,
    clientName
  ) {
    kind = String(kind || "").trim().toLowerCase();
    requestName = String(requestName || "").trim();

    /*
      Backward-compatible protection for older buttons that still carry
      data-workflow-all. C2C and P2P both have deterministic direct routes now,
      so open the exact record and stop before the old popup polling loop.
    */
    if (
      kind === "c2c" ||
      kind === "p2p"
    ) {
      var directPath =
        kind === "p2p"
          ? "/package-conversion-for-p2p"
          : "/package-conversion-c2c";

      var directHref =
        directPath +
        "?tab=all" +
        (
          requestName
            ? "&request=" + encodeURIComponent(requestName)
            : ""
        );

      var directPopup = window.open(
        directHref,
        "_blank"
      );

      if (!directPopup) {
        toast(
          "Allow popups for this portal and click View Request again"
        );
        return;
      }

      try {
        directPopup.opener = null;
      } catch (ignoreDirectPopupOpener) {}

      return;
    }

    var config;

    if (kind === "b2b") {
      config = {
        path: "/b2b-testing",
        tabId: "life-mode-1",
        panelId: "b2b-list-panel"
      };
    } else if (kind === "p2p") {
      config = {
        path: "/package-conversion-for-p2p",
        tabSelector: '.pkg-tab[data-tab="1"]',
        panelId: "pkgTab1",
        listSelector: "#pkgAllRequestsList"
      };
    } else {
      config = {
        path: "/package-conversion-c2c",
        tabId: "navTab1",
        panelId: "mode-1"
      };
    }

    var href =
      config.path +
      "?coo_view=all_requests" +
      "&coo_focus_version=p2p_selected_first_v2";

    if (requestName) {
      href +=
        "&coo_request=" +
        encodeURIComponent(requestName);
    }

    if (clientName) {
      href +=
        "&coo_client=" +
        encodeURIComponent(clientName);
    }

    var popup =
      window.open(
        href,
        "_blank"
      );

    if (!popup) {
      toast(
        "Allow popups for this portal and click Review again"
      );
      return;
    }

    var attempts = 0;
    var stableHits = 0;
    var selectedRequestFocused =
      !requestName &&
      !clientName;

    var selectedAt = 0;
    var lastTabClick = 0;
    var b2bAllRequestsPrepared = false;

    var focusState = {
      lastNextClick: 0,
      pagesChecked: 0
    };

    /*
      B2B View Request must always open the All Requests register with the
      STATUS filter set to All. Without this, a COO login can leave the
      B2B page on "COO / Management Pending"; then Branch Manager/Audit
      records disappear and the selected request cannot be opened.
    */
    function forceB2BAllRequests(
      doc,
      tab,
      panel
    ) {
      if (
        kind !== "b2b" ||
        !doc
      ) {
        return;
      }

      /* Keep the B2B page on All Requests. */
      if (
        popup.B2B &&
        typeof popup.B2B.switchMode === "function"
      ) {
        var b2bActive = !!(
          tab &&
          tab.classList.contains("active") &&
          panel &&
          panel.style.display !== "none"
        );

        if (!b2bActive) {
          try {
            popup.B2B.switchMode(1);
          } catch (ignoreB2BSwitch) {}
        }
      } else if (tab) {
        try {
          if (!tab.classList.contains("active")) tab.click();
        } catch (ignoreB2BTabClick) {}
      }

      var statusFilter =
        doc.getElementById("b2b-status-filter");

      if (!statusFilter) {
        return;
      }

      var allValue = null;

      Array.prototype.some.call(
        statusFilter.options || [],
        function (option) {
          var optionText = String(
            option.textContent || option.text || ""
          ).replace(/\s+/g, " ").trim().toLowerCase();

          var optionValue = String(
            option.value == null ? "" : option.value
          ).trim();

          if (
            optionText === "all" ||
            optionText === "all statuses" ||
            optionValue === "" ||
            optionValue.toLowerCase() === "all"
          ) {
            allValue = option.value;
            return true;
          }

          return false;
        }
      );

      if (allValue === null) {
        return;
      }

      if (String(statusFilter.value) !== String(allValue)) {
        statusFilter.value = allValue;
      }

      if (!b2bAllRequestsPrepared) {
        b2bAllRequestsPrepared = true;

        try {
          if (
            popup.B2B &&
            typeof popup.B2B.setAllRequestStatusFilter === "function"
          ) {
            popup.B2B.setAllRequestStatusFilter();
          } else {
            statusFilter.dispatchEvent(
              new popup.Event("change", { bubbles: true })
            );
          }
        } catch (ignoreB2BFilterChange) {}

        /* Reload once after clearing the filter so the selected request can
           be found even if the first role-filtered render was empty. */
        try {
          if (
            popup.B2B &&
            typeof popup.B2B.refreshAllRequests === "function"
          ) {
            popup.B2B.refreshAllRequests();
          }
        } catch (ignoreB2BRefresh) {}

        void 0;
      }
    }

    function forceP2PAllRequests(
      doc,
      tab,
      panel
    ) {
      if (
        kind !== "p2p" ||
        !doc ||
        !tab ||
        !panel
      ) {
        return;
      }

      /*
        Keep All Requests selected even if the P2P page's own startup or
        reset logic tries to return to New Conversion Request.
      */
      doc.querySelectorAll(
        ".pkg-tab"
      ).forEach(function (item) {
        item.classList.toggle(
          "active",
          item === tab
        );
      });

      doc.querySelectorAll(
        ".pkg-panel"
      ).forEach(function (item) {
        item.style.display =
          item === panel
            ? "block"
            : "none";
      });

      var stepBar =
        doc.getElementById(
          "pkgStepBar"
        );

      if (stepBar) {
        stepBar.style.display =
          "none";
      }

      var now =
        Date.now();

      /*
        Trigger the P2P page's own tab listener periodically. This calls
        renderAllRequests() after the page script has finished binding.
      */
      if (
        !lastTabClick ||
        now - lastTabClick >= 700
      ) {
        lastTabClick = now;

        try {
          tab.dispatchEvent(
            new popup.MouseEvent(
              "click",
              {
                bubbles: true,
                cancelable: true,
                view: popup
              }
            )
          );
        } catch (dispatchError) {
          try {
            tab.click();
          } catch (clickError) {
            /* Continue retrying while the P2P page starts. */
          }
        }
      }
    }

    var timer =
      window.setInterval(
        function () {
          attempts += 1;

          if (
            !popup ||
            popup.closed
          ) {
            window.clearInterval(
              timer
            );
            return;
          }

          try {
            var doc =
              popup.document;

            var tab = null;

            if (doc) {
              if (
                config.tabSelector
              ) {
                tab =
                  doc.querySelector(
                    config.tabSelector
                  );
              } else if (
                config.tabId
              ) {
                tab =
                  doc.getElementById(
                    config.tabId
                  );
              }
            }

            var panel =
              doc &&
              config.panelId
                ? doc.getElementById(
                    config.panelId
                  )
                : null;

            if (
              kind === "b2b"
            ) {
              forceB2BAllRequests(
                doc,
                tab,
                panel
              );
            }

            if (
              kind === "p2p"
            ) {
              forceP2PAllRequests(
                doc,
                tab,
                panel
              );
            }

            var active = false;

            if (
              kind === "b2b" &&
              popup.B2B &&
              typeof popup.B2B.switchMode ===
                "function"
            ) {
              active = !!(
                tab &&
                tab.classList.contains(
                  "active"
                ) &&
                panel &&
                panel.style.display !==
                  "none"
              );

              if (!active) {
                popup.B2B.switchMode(
                  1
                );
              }
            } else if (
              tab
            ) {
              active = !!(
                (
                  tab.classList.contains(
                    "on"
                  ) ||
                  tab.classList.contains(
                    "active"
                  )
                ) &&
                (
                  !panel ||
                  panel.style.display !==
                    "none"
                )
              );

              if (
                !active &&
                kind !== "p2p"
              ) {
                tab.click();
              }
            }

            /*
              For P2P, do not mark the view ready until the request list
              has actually rendered. A tab can look active before its own
              script has loaded the list.
            */
            if (
              active &&
              kind === "p2p" &&
              config.listSelector
            ) {
              var listHost =
                doc.querySelector(
                  config.listSelector
                );

              active = !!(
                listHost &&
                (
                  listHost.querySelector(
                    ".pkg-request-item"
                  ) ||
                  workflowTargetText(
                    listHost.textContent ||
                    ""
                  ).indexOf(
                    "no requests found"
                  ) >= 0
                )
              );
            }

            if (active) {
              stableHits += 1;

              if (
                !selectedRequestFocused
              ) {
                selectedRequestFocused =
                  workflowFocusSelectedRequest(
                    popup,
                    config,
                    kind,
                    requestName,
                    clientName,
                    focusState
                  );

                if (
                  selectedRequestFocused
                ) {
                  selectedAt =
                    Date.now();
                }
              }
            } else {
              stableHits = 0;
            }

            /*
              Keep forcing the P2P All Requests tab for four seconds after
              the selected request is found and opened. This prevents the
              page from flashing back to Step 1 / New Conversion Request.
            */
            var p2pSettled =
              kind !== "p2p" ||
              (
                selectedRequestFocused &&
                selectedAt &&
                Date.now() -
                  selectedAt >=
                  4000
              );

            if (
              stableHits >= 8 &&
              selectedRequestFocused &&
              p2pSettled
            ) {
              window.clearInterval(
                timer
              );
            }
          } catch (error) {
            /*
              The same-origin ERPNext Web Page may still be loading.
              Continue retrying.
            */
          }

          if (
            attempts >= 240
          ) {
            window.clearInterval(
              timer
            );
          }
        },
        250
      );
  }

  function deskLink(dt, dn) {
