          bm[branchName] = {
            b: branchName, n: 0, f: 0, joins: 0,
            present: 0, checkedIn: 0, checkedOut: 0, absentLeave: 0
          };
        }
        bm[branchName].n++;
        if (r.gender === "Female") bm[branchName].f++;
        if (r.date_of_joining && r.date_of_joining >= rangeFrom() && r.date_of_joining <= rangeTo()) {
          bm[branchName].joins++;
        }
        var attendance = attendanceByEmployee[r.name];
        if (attendance) {
          if (attendance.status === "Present") bm[branchName].present++;
          if (attendance.status === "Absent" || attendance.status === "On Leave" ||
              attendance.status === "Half Day") bm[branchName].absentLeave++;
          if (attendanceDateTimeValue(attendance, "in")) bm[branchName].checkedIn++;
          if (attendanceDateTimeValue(attendance, "out")) bm[branchName].checkedOut++;
        }
      });

      var bl = Object.keys(bm).map(function (key) { return bm[key]; })
        .sort(function (a, b) { return b.n - a.n; });

      var totalPresent = bl.reduce(function (sumValue, row) {
        return sumValue + row.present;
      }, 0);
      var totalCheckedIn = bl.reduce(function (sumValue, row) {
        return sumValue + row.checkedIn;
      }, 0);
      var totalCheckedOut = bl.reduce(function (sumValue, row) {
        return sumValue + row.checkedOut;
      }, 0);
      var totalAbsentLeave = bl.reduce(function (sumValue, row) {
        return sumValue + row.absentLeave;
      }, 0);

