        { v: totalCheckedOut, l: "checked out", c: totalCheckedOut ? "g" : "" },
        { v: totalAbsentLeave, l: "absent / leave", c: totalAbsentLeave ? "r" : "" },
        { v: emp.filter(function (r) {
