            esc(ticketMetaData.resolution_remarks) + "</div>"
          : "") +
        (ticketMetaData.reopen_review_remarks
          ? '<div class="sec-h">Reopen remarks</div><div class="note">' +
            esc(ticketMetaData.reopen_review_remarks) + "</div>"
          : "") +
        workHistoryHtml(ticketMetaData);
      return;
