      var accountWarning = state.err.accountsPage
        ? '<div class="err" style="margin-bottom:10px">' + esc(state.err.accountsPage) + "</div>"
        : "";
      var pes = peRows();
      var tot2 = 0;
      var tot2Net = 0;
      var tot2LoanCut = 0;
      var tot2FiveCut = 0;
      var mm2 = {};

      pes.forEach(function (r) {
        var m = r.mode_of_payment || "Unspecified";
        var calc = targetPaymentCalculation(r);

        if (!mm2[m]) {
          mm2[m] = {
            n: m,
            v: 0,
            c: 0,
            net: 0,
            loanCut: 0,
            fiveCut: 0,
            loan: isLoanMode(m)
          };
        }

        mm2[m].v += calc.gross;
        mm2[m].net += calc.net;
        mm2[m].loanCut += calc.loan_cut;
        mm2[m].fiveCut += calc.five_percent_cut;
        mm2[m].c++;

        tot2 += calc.gross;
        tot2Net += calc.net;
        tot2LoanCut += calc.loan_cut;
        tot2FiveCut += calc.five_percent_cut;
      });

      var ml = Object.keys(mm2).map(function (k) {
        return mm2[k];
      }).sort(function (a, b) { return b.v - a.v; });

      kpis([{ v: inrS(tot2), l: "gross collected", c: "g" },
            { v: inrS(tot2Net), l: "final net" },
            { v: inrS(tot2LoanCut), l: "loan processing 15%", c: "r" },
            { v: inrS(tot2FiveCut), l: "GST / 5% cut" },
            { v: pes.length, l: "payments" }, { v: ml.length, l: "modes" },
            { v: inrS(sum(ccRows(), "outstanding_amount")), l: "cc outstanding", c: "r" }]);

      body.innerHTML = accountWarning +
        '<div class="note" style="margin-bottom:10px"><b>Loan formula verified — Accounts v4:</b> Normal modes = Gross × 100 ÷ 105. Loan / finance modes = Gross − 15% processing − 5% of the remaining balance. This exactly matches Target vs Achievement.</div>' +
        table(
        [{ t: "Mode of payment" }, { t: "Entries", rt: 1 },
         { t: "Gross", rt: 1 }, { t: "Loan cut 15%", rt: 1 },
         { t: "GST / 5%", rt: 1 }, { t: "Final net", rt: 1 },
         { t: "Share", rt: 1 }, { t: "" }],
        ml.map(function (m) {
