  /* ================= LEVEL 3: complete view ================= */
  function fkpis(a) {
    return '<div class="f-kpis">' + a.map(function (k) {
      return '<div class="f-kpi"><b class="' + (k.c || "") + '">' + k.v + "</b><span>" +
        k.l + "</span></div>";
    }).join("") + "</div>";
  }
  function fCard(h, body) {
    return '<div class="f-card"><h3>' + esc(h) + "</h3>" + body + "</div>";
  }

  /*
    Collapsible sections used only inside My Approvals.
    All long approval tables start closed, and the user can open/close
    one section or all sections without leaving the dashboard.
  */
  function approvalSection(title, content, openByDefault) {
    return '<details class="coo-approval-section"' +
      (openByDefault ? " open" : "") +
      ' style="margin:12px 0;border:1px solid #DCE9DE;border-radius:12px;' +
