    if (kind === "disc") {
      return row.linked_invoice
        ? goLink("Sales Invoice", row.linked_invoice, "Review")
        : "<span class='wm'>No invoice</span>";
    }

    if (kind === "po") {
      return goLink("Purchase Order", row.name, "Review");
    }

    /*
      In the special COO Pending - All Dates view, P2P/C2C/B2B request
      buttons must open the workflow's All Requests tab, not the Approval
      Dashboard. The normal date-based Pending at COO view keeps its existing
      direct COO approval links.
