    if (kind === "c2c") {
      if (forceAllRequests) {
        return workflowAllRequestsLink(
          "c2c",
          "View Request",
          row.name,
          row.name1 || row.client_full_name || row.client_name || ""
        );
      }

      return approvalCurrentActionRequired(kind, row)
        ? c2cCooApprovalLink(row.name, "Review COO Approval")
        : workflowAllRequestsLink(
            "c2c",
            "View Request",
            row.name,
            row.name1 || row.client_full_name || row.client_name || ""
