      return approvalCurrentActionRequired(kind, row)
        ? p2pCooApprovalLink(row.name, "Review COO Approval")
        : workflowAllRequestsLink(
            "p2p",
            "View Request",
            row.name,
            row.client_name || ""
          );
    }

    return workflowAllRequestsLink(
      "b2b",
      "View Request",
      row.name,
      row.client_full_name || row.client || ""
