          return approvalTableRow("c2c", row,
            "<td><div class='wn'>" + esc(row.name) + "</div></td>" +
            "<td>" + esc(row.name1 || row.client_full_name || row.client_name || "\u2014") + "</td>" +
            "<td>" + esc(row.branch || "\u2014") + "</td>" +
