  function mapToChart(map) {
    return Object.keys(map || {}).map(function (key) {
      return { n: key, v: map[key] };
    }).sort(function (a, b2) { return b2.v - a.v; });
  }

  function barChart(rows, fmt) {
    if (!rows.length) return '<div class="empty">No data.</div>';
    var mx = Math.max.apply(null, rows.map(function (r) { return r.v; })) || 1;
    return '<div class="bc">' + rows.map(function (r) {
      return '<div class="bc-row"><div class="bc-n" title="' + esc(r.n) + '">' + esc(r.n) +
        '</div><div class="bc-t"><i style="width:' + Math.max(pct(r.v, mx), 1) +
        '%"></i></div><div class="bc-v">' + (fmt ? fmt(r.v) : r.v) + "</div></div>";
    }).join("") + "</div>";
  }

  /* which tiles have a level-3 view */
  var FULL_OK = { sales:1, branches:1, callcentre:1, accounts:1, appointments:1, targets:1,
                  service:1, stock:1, hr:1, tasks:1, tickets:1, assets:1,
                  approvals:1, grievance:1 };

  var activeFull = null;

  function refreshFull(t) {
    renderContextTile = t;
    try {
      renderFull(t);
    } finally {
      renderContextTile = "";
    }
    prependRangeFilter($("[data-f-body]"), t);
  }

  function showPopupOverlayAgain() {
    var overlay = $("[data-ovl]");
    if (!overlay || !nav.length) return;

    overlay.classList.add("on");
    overlay.setAttribute("aria-hidden", "false");
    overlay.style.display = "flex";
    overlay.style.position = "fixed";
    overlay.style.inset = "0";
    overlay.style.zIndex = "999999";
  }

  function openFull(t) {
    var overlay = $("[data-ovl]");
    var full = $("[data-full]");
    var fullBody = $("[data-f-body]");

    if (!t || !full || !fullBody) {
      void 0;
      return;
    }

    activeFull = t;
    ensureAppointmentPageRange(t);

    var fullRange = appointmentPageRange(t);
    var fullBranch = fullRange.branch || "ALL";
    $("[data-f-bc]").textContent = t === "targets"
      ? (fullBranch === "ALL" ? "All Branches" : fullBranch) + " \u00B7 Range view (Collections)"
      : (TITLES[t] || t);
    $("[data-f-title]").textContent = t === "targets"
      ? "Target & Realisation (Range: " + fullRange.from + " \u2192 " + fullRange.to + ")"
      : (TITLES[t] || t) + " \u2014 Complete Report";
    $("[data-f-title]").style.color = "#FFFFFF";
    fullBody.innerHTML = '<div class="empty">Building complete report\u2026</div>';

    /* openModal() adds inline display/z-index to the popup overlay. Merely
       removing the .on class is not enough, because the inline display:flex
       keeps that overlay above the Complete View. Hide it explicitly. */
    if (overlay) {
      overlay.classList.remove("on");
      overlay.setAttribute("aria-hidden", "true");
      overlay.style.display = "none";
    }

    /* Force the Complete View above the ERPNext website shell. */
    full.classList.add("on");
    full.style.display = "flex";
    full.style.position = "fixed";
    full.style.inset = "0";
    full.style.zIndex = "1000000";

    /* Let the full-page shell paint before building tables/charts. */
    window.setTimeout(function () {
      try {
        refreshFull(t);
        fullBody.scrollTop = 0;
      } catch (error) {
        void 0;
        fullBody.innerHTML =
          '<div class="err"><b>Complete View could not be rendered.</b><br>' +
          esc((error && error.message) || String(error)) +
          '<br><small>The dashboard popup is still available through the Back button.</small></div>';
      }
    }, 20);
  }

  function closeFull() {
    var full = $("[data-full]");
    if (full) {
      full.classList.remove("on");
      full.style.display = "none";
    }
    activeFull = null;
  }

  function renderFull(t) {
    var b = $("[data-f-body]");
    var sr = salesRows(), cr = ccRows();
    var selectedScopeBranch = effectiveBranch();
    var scope = selectedScopeBranch === "ALL" ? "All 11 branches" : selectedScopeBranch;

    if (t === "sales" || t === "branches") {
      var brs = byBranch(), cats = byCategory(), tot = salesCollectedTotal();
      b.innerHTML =
        fkpis([{ v: inrS(tot), l: "With GST", c: "g" },
               { v: inrS(salesNetTotal()), l: "Without GST" },
               { v: inrS(salesTaxTotal()), l: "GST" },
               { v: salesInvoiceCount(), l: "Invoices" },
               { v: brs.length, l: "Branches" },
               { v: brs.length ? esc(brs[0].branch) : "\u2014", l: "Top branch", c: "bl" }]) +
        '<div class="f-2col">' +
        fCard("Collections by branch (With GST)", barChart(brs.map(function (x) {
          return { n: x.branch, v: x.paid }; }), inrS)) +
        fCard("Collections by category (With GST)", barChart(cats.map(function (x) {
          return { n: x.cat, v: x.paid }; }), inrS)) +
        "</div>" +
        fCard("Branch detail \u2014 " + scope,
          table([{ t: "Branch" }, { t: "Invoices", rt: 1 }, { t: "With GST", rt: 1 },
                 { t: "Without GST", rt: 1 }, { t: "GST", rt: 1 }, { t: "Share", rt: 1 }],
            brs.map(function (x) {
              return "<tr><td><div class='wn'>" + esc(x.branch) + "</div></td>" +
                "<td class='rt'>" + x.inv + "</td>" +
                "<td class='rt'><b>" + inr(x.paid) + "</b></td>" +
                "<td class='rt'>" + inr(x.net) + "</td>" +
                "<td class='rt'>" + inr(x.tax) + "</td>" +
                "<td class='rt'>" + pct(x.paid, tot) + "%</td></tr>";
            })));
      return;
    }

    if (t === "callcentre") {
      var src = bySource(), ag = byAgent();
      var gt = sum(cr, "grand_total"), pd = sum(cr, "paid_amount");
      b.innerHTML =
        fkpis([{ v: cr.length, l: "CC invoices" }, { v: inrS(gt), l: "Billed" },
               { v: inrS(pd), l: "Collected", c: "g" },
               { v: inrS(sum(cr, "outstanding_amount")), l: "Outstanding", c: "r" },
               { v: pct(pd, gt) + "%", l: "Realised" },
               { v: cr.filter(function (r) { return r.lead_status === "Converted"; }).length,
                 l: "Converted", c: "bl" }]) +
        '<div class="f-2col">' +
        fCard("Collections by source", barChart(src.map(function (x) {
          return { n: x.src, v: x.paid }; }), inrS)) +
        fCard("Invoice count by source", barChart(src.map(function (x) {
          return { n: x.src, v: x.n }; }))) +
        "</div>" +
        fCard("Agent performance",
          table([{ t: "Agent" }, { t: "Invoices", rt: 1 }, { t: "Collected", rt: 1 },
                 { t: "Outstanding", rt: 1 }, { t: "Share", rt: 1 }],
            ag.map(function (a) {
              return "<tr><td><div class='wn'>" + esc(a.agent) + "</div></td>" +
                "<td class='rt'>" + a.n + "</td>" +
                "<td class='rt'><b>" + inr(a.paid) + "</b></td>" +
                "<td class='rt'>" + (a.out > 0 ? inr(a.out) : "\u2014") + "</td>" +
                "<td class='rt'>" + pct(a.paid, pd) + "%</td></tr>";
            })));
      return;
    }

    if (t === "accounts") {
      var pes = peRows();
      var tot3 = 0;
      var tot3Net = 0;
      var tot3LoanCut = 0;
      var tot3FiveCut = 0;
      var mm = {}, cc2 = {};

      pes.forEach(function (r) {
        var calc = targetPaymentCalculation(r);
        var m = r.mode_of_payment || "Unspecified";

        if (!mm[m]) {
          mm[m] = { n: m, v: 0, net: 0, loanCut: 0, fiveCut: 0 };
        }

        mm[m].v += calc.gross;
        mm[m].net += calc.net;
        mm[m].loanCut += calc.loan_cut;
        mm[m].fiveCut += calc.five_percent_cut;

        tot3 += calc.gross;
        tot3Net += calc.net;
        tot3LoanCut += calc.loan_cut;
        tot3FiveCut += calc.five_percent_cut;

        var c = r.cost_center || "Unassigned";
        cc2[c] = (cc2[c] || 0) + calc.gross;
      });

      var ml = Object.keys(mm).map(function (k) { return mm[k]; })
        .sort(function (a, b2) { return b2.v - a.v; });
      var cl3 = Object.keys(cc2).map(function (k) { return { n: k, v: cc2[k] }; })
        .sort(function (a, b2) { return b2.v - a.v; });
      var cashGross = mm["Cash"] ? mm["Cash"].v : 0;

      b.innerHTML =
        fkpis([{ v: inrS(tot3), l: "Gross collected", c: "g" },
               { v: inrS(tot3Net), l: "Final net" },
               { v: inrS(tot3LoanCut), l: "Loan processing 15%", c: "r" },
               { v: inrS(tot3FiveCut), l: "GST / 5% cut" },
               { v: pes.length, l: "Payment entries" },
               { v: inrS(cashGross), l: "Cash (Gross)" },
               { v: inrS(tot3 - cashGross), l: "Non-cash (Gross)" },
               { v: inrS(sum(cr, "outstanding_amount")), l: "CC outstanding", c: "r" },
               { v: ml.length, l: "Payment modes" }]) +
        '<div class="note" style="margin-bottom:12px">Normal modes: Gross × 100 ÷ 105. Loan / finance modes: Gross − 15% processing, then − 5% from the balance.</div>' +
        '<div class="f-2col">' +
        fCard("By mode of payment (Gross)", barChart(ml.map(function (r) {
          return { n: r.n, v: r.v };
        }), inrS)) +
        fCard("By cost centre (Gross)", barChart(cl3.slice(0, 12), inrS)) +
        "</div>" +
        fCard("Payments in selected range",
          table([{ t: "Payment" }, { t: "Date" }, { t: "Party" }, { t: "Mode" },
                 { t: "Gross", rt: 1 }, { t: "Loan cut 15%", rt: 1 },
                 { t: "GST / 5%", rt: 1 }, { t: "Final net", rt: 1 }],
            pes.slice(0, 80).map(function (r) {
              var calc = targetPaymentCalculation(r);
              return "<tr><td><div class='wn'>" + esc(r.name) + "</div></td>" +
                "<td>" + esc(r.posting_date) + "</td>" +
                "<td>" + esc(r.party_name || "\u2014") + "</td>" +
                "<td>" + esc(r.mode_of_payment || "\u2014") + "</td>" +
                "<td class='rt'><b>" + inr(calc.gross) + "</b></td>" +
                "<td class='rt'>" + (calc.loan_cut ? inr(calc.loan_cut) : "—") + "</td>" +
                "<td class='rt'>" + inr(calc.five_percent_cut) + "</td>" +
                "<td class='rt'><b>" + inr(calc.net) + "</b></td></tr>";
            })));
      return;
    }

    if (t === "appointments") {
      var aptFull = appointmentPageRows("appointments");
      var appointmentDepartmentMap = {};
      var appointmentBranchMap = {};

      aptFull.forEach(function (r) {
        var department = serviceDepartmentFromAppointment(r);
        appointmentDepartmentMap[department] =
          (appointmentDepartmentMap[department] || 0) + 1;
        var branch = r.branch || "Unassigned";
        appointmentBranchMap[branch] =
          (appointmentBranchMap[branch] || 0) + 1;
      });

      var appointmentDepartments = Object.keys(appointmentDepartmentMap)
        .map(function (key) {
          return { n: key, v: appointmentDepartmentMap[key] };
        })
        .sort(function (a, b2) { return b2.v - a.v; });

      var appointmentBranches = Object.keys(appointmentBranchMap)
        .map(function (key) {
          return { n: key, v: appointmentBranchMap[key] };
        })
        .sort(function (a, b2) { return b2.v - a.v; });

      var appointmentDone = aptFull.filter(isAppointmentCompleted).length;
      var appointmentFullSessionData = appointmentSessionMatchData(aptFull);

      b.innerHTML =
        fkpis([{ v: aptFull.length, l: "Appointments" },
               { v: appointmentFullSessionData.entered, l: "Session Entered", c: "g" },
               { v: appointmentFullSessionData.notEntered, l: "Session Not Entered", c: "r" },
               { v: appointmentDone, l: "Completed", c: "g" },
               { v: aptFull.filter(isAppointmentCheckedIn).length,
                 l: "Checked in", c: "bl" },
               { v: aptFull.filter(isAppointmentNoShow).length,
                 l: "No show", c: "r" },
               { v: aptFull.filter(isAppointmentCancelled).length,
                 l: "Cancelled", c: "a" },
               { v: pct(appointmentDone, aptFull.length) + "%",
                 l: "Completion" }]) +
        '<div class="f-2col">' +
        fCard("By department", barChart(appointmentDepartments)) +
        fCard("By branch", barChart(appointmentBranches)) +
        "</div>" +
        fCard("All appointments \u2014 " +
          appointmentPageRangeText("appointments"),
          (aptFull.length > 300
            ? '<div class="note">Showing the first 300 of ' + aptFull.length +
              ' appointments. Narrow the date or branch filter for a smaller register.</div>'
            : "") +
          (function () {
            var completeRows = aptFull.slice(0, 300);
            var completeLastSessions = appointmentLastSessionMap(completeRows);
            return table([{ t: "Date & Time" }, { t: "Client" },
                 { t: "Department / Branch" },
                 { t: "Therapy" }, { t: "Therapy Session" },
                 { t: "Last Session Entry" },
