  function salesFrappeCallWithRetry(options, maxAttempts) {
    maxAttempts =
      Math.max(
        parseInt(maxAttempts, 10) || 1,
        1
      );

    return new Promise(function (resolve, reject) {
      var attempt = 0;

      function run() {
        attempt += 1;

        frappe.call({
          method: options.method,
          args: options.args,
          freeze: false,
          callback: function (response) {
            resolve(response);
          },
          error: function (error) {
            if (attempt < maxAttempts) {
              void 0;

              window.setTimeout(
                run,
                attempt * 700
              );

              return;
            }

            reject(error);
          }
        });
      }

      run();
    });
  }


  function loadSalesPageRange(
