    state.pageRanges[tileKey] = {
      from: fromDate,
      to: toDate,
      preset: preset || "custom",
      branch: localBranch
    };

    if (state.pageData) {
      delete state.pageData[tileKey];
    }

    state.err.salesPage = "";
    setPageRangeButtonBusy(button, true);

    var invoiceFilters = [
      ["docstatus", "=", 1],
      ["is_return", "=", 0],
      ["posting_date", ">=", fromDate],
      ["posting_date", "<=", toDate]
    ];

    var paymentFilters = [
      ["docstatus", "=", 1],
      ["payment_type", "=", "Receive"],
      ["posting_date", ">=", fromDate],
      ["posting_date", "<=", toDate]
    ];

    if (localBranch !== "ALL") {
      invoiceFilters.push(["branch", "=", localBranch]);
      paymentFilters.push(["branch", "=", localBranch]);
    }

    function fetchAllPages(doctype, fields, filters, orderBy, errorLabel) {
      var pageLength = 500;

      function fetchPage(start, collected) {
        return salesFrappeCallWithRetry(
          {
            method: "frappe.client.get_list",
            args: {
              doctype: doctype,
              fields: fields,
              filters: filters,
              order_by: orderBy,
              limit_start: start,
              limit_page_length: pageLength
            }
          },
          3
        )
          .then(function (response) {
            var batch =
              (response && response.message) ||
              [];

            var next =
              collected.concat(batch);

            if (batch.length === pageLength) {
              return fetchPage(
                start + pageLength,
                next
              );
            }

            return {
              ok: true,
              rows: next
            };
          })
          .catch(function (error) {
            void 0;

            return {
              ok: false,
              rows: []
            };
          });
      }

      return fetchPage(0, []);
    }

    var invoicePromise = fetchAllPages(
      "Sales Invoice",
      [
        "name",
        "posting_date",
        "customer",
        "customer_name",
        "patient",
        "patient_name",
        "branch",
        "custom_transfer_branch",
        "service_unit",
        "therapy_plan_reference_id",
        "custom_tele_caller",
        "currency",
        "base_grand_total",
        "base_rounded_total",
        "rounded_total",
        "grand_total",
        "base_net_total",
        "net_total",
        "base_total_taxes_and_charges",
        "total_taxes_and_charges",
        "outstanding_amount",
        "disable_rounded_total",
        "status",
        "docstatus",
        "is_return",
        "modified"
      ],
      invoiceFilters,
      "posting_date desc, modified desc",
      "Exact Sales Invoice load failed"
    );

    var paymentPromise = fetchAllPages(
      "Payment Entry",
      [
        "name",
        "posting_date",
        "payment_type",
        "mode_of_payment",
        "paid_amount",
        "received_amount",
        "base_received_amount",
        "base_paid_amount",
        "party_name",
        "cost_center",
        "branch",
        "docstatus"
      ],
      paymentFilters,
      "posting_date desc, modified desc",
      "Exact Payment Entry load failed"
    );

    var reportPromise = runReport(
      RPT_SALES,
      {
        from_date: fromDate,
        to_date: toDate
      }
    )
      .then(function (rows) {
        rows = rows || [];

        if (localBranch !== "ALL") {
          rows = rows.filter(function (row) {
            return String(row.branch || "") === localBranch;
          });
        }

        return {
          ok: true,
          rows: rows
        };
      })
      .catch(function (error) {
        void 0;

        return {
          ok: false,
          rows: []
        };
      });

    return Promise.all([
      invoicePromise,
      paymentPromise,
      reportPromise
    ])
      .then(function (results) {
        var invoiceResult = results[0];
        var paymentResult = results[1];
        var reportResult = results[2];

        var exactInvoices =
          (invoiceResult.rows || []).filter(function (row) {
            var postingDate =
              String(row.posting_date || "").slice(0, 10);

            return (
              postingDate >= fromDate &&
              postingDate <= toDate &&
              (localBranch === "ALL" || String(row.branch || "") === localBranch) &&
              Number(row.docstatus) === 1 &&
              Number(row.is_return || 0) !== 1
            );
          });

        var exactPayments =
          (paymentResult.rows || []).filter(function (row) {
            var postingDate =
              String(row.posting_date || "").slice(0, 10);

            return (
              postingDate >= fromDate &&
              postingDate <= toDate &&
              (localBranch === "ALL" || String(row.branch || "") === localBranch) &&
              Number(row.docstatus) === 1 &&
              String(row.payment_type || "") === "Receive"
            );
          });

        exactPayments.forEach(function (row) {
          row.paid_amount =
            parseFloat(row.base_received_amount) ||
            parseFloat(row.received_amount) ||
            parseFloat(row.base_paid_amount) ||
            parseFloat(row.paid_amount) ||
            0;
        });

        state.pageData[tileKey] = {
          sales: reportResult.ok
            ? reportResult.rows
            : [],
          invoices: invoiceResult.ok
            ? exactInvoices
            : [],
          payments: paymentResult.ok
            ? exactPayments
            : []
        };

        state.err.salesPage =
          invoiceResult.ok && paymentResult.ok
            ? ""
            : "Sales Summary could not load all exact Sales Invoice and Payment Entry records. Click Apply again.";

        if (
          nav.length &&
          canonicalSalesRangeTile(nav[0].t) === tileKey
        ) {
          nav = [nav[0]];
          paint();
        }

        if (activeFull === tileKey) {
          refreshFull(tileKey);
        }

        var gross = exactPayments.reduce(function (total, row) {
