    e.preventDefault();
    e.stopPropagation();

    var host = tab.closest("[data-m-body], [data-f-body]") || root;
    var key = tab.getAttribute("data-service-tab");

    host.querySelectorAll("[data-service-tab]").forEach(function (button) {
      var active = button === tab;
      button.classList.toggle("active", active);
      button.setAttribute("aria-selected", active ? "true" : "false");
    });

    host.querySelectorAll("[data-service-panel]").forEach(function (panel) {
      panel.hidden = panel.getAttribute("data-service-panel") !== key;
    });
  });

  /* Task popup and complete-view tabs. */
  root.addEventListener("click", function (e) {
    var tab = e.target.closest("[data-task-tab]");
    if (!tab || !root.contains(tab)) return;

    e.preventDefault();
    e.stopPropagation();

    var host = tab.closest("[data-m-body], [data-f-body]") || root;
    var key = tab.getAttribute("data-task-tab");

    host.querySelectorAll("[data-task-tab]").forEach(function (button) {
      var active = button === tab;
      button.classList.toggle("active", active);
      button.setAttribute("aria-selected", active ? "true" : "false");
    });

    host.querySelectorAll("[data-task-panel]").forEach(function (panel) {
      panel.hidden = panel.getAttribute("data-task-panel") !== key;
    });
  });

  /* C2C and B2B View All Requests buttons open the corresponding workflow
     page and select its All Requests tab after that page finishes loading. */
  root.addEventListener("click", function (e) {
    var link = e.target.closest("[data-workflow-all]");
    if (!link || !root.contains(link)) return;

    e.preventDefault();
    e.stopPropagation();
    e.stopImmediatePropagation();

    openWorkflowAllRequests(
      link.getAttribute("data-workflow-all"),
      link.getAttribute("data-workflow-request"),
      link.getAttribute("data-workflow-client")
    );
  }, true);


  /*
    Open or close every My Approvals section in the currently visible
    modal or complete report.
  */
  root.addEventListener("click", function (e) {
    var button = e.target.closest("[data-approval-sections-action]");
    if (!button || !root.contains(button)) return;

    e.preventDefault();
    e.stopPropagation();

    var action = button.getAttribute("data-approval-sections-action");
    var host =
      button.closest("[data-m-body]") ||
      button.closest("[data-f-body]") ||
      root;

    host.querySelectorAll("details.coo-approval-section").forEach(function (section) {
      section.open = action === "open";
    });
  }, true);

  /*
    Task View and Open All Tasks Report both open the embedded standalone
    Task Manager directly on Task Management → All Tasks Report.
  */
  root.addEventListener("click", function (e) {
    var button = e.target.closest("[data-embedded-task-report]");
    if (!button || !root.contains(button)) return;

    e.preventDefault();
    e.stopPropagation();
    e.stopImmediatePropagation();

    openLifeWorkSystem(
      "task",
      "report",
      button.getAttribute(
        "data-embedded-task-report"
      ) || ""
    );
  }, true);

  /*
    Ticket row View and Open All Tickets Report both open the exact same
    embedded standalone dashboard:
      Ticket / Helpdesk → All Tickets Report

    A unique attribute is used so no old route-discovery listener can catch
    this click.
  */
  root.addEventListener("click", function (e) {
    var button = e.target.closest("[data-embedded-ticket-report]");
    if (!button || !root.contains(button)) return;

    e.preventDefault();
    e.stopPropagation();
    e.stopImmediatePropagation();

    openLifeWorkSystem(
      "ticket",
      "report",
      button.getAttribute(
        "data-embedded-ticket-report"
      ) || ""
    );
  }, true);

  /* Details inside My Tickets open the selected Issue detail in the same COO popup. */
  root.addEventListener("click", function (e) {
    var button = e.target.closest("[data-ticket-detail-view]");
    if (!button || !root.contains(button)) return;
    e.preventDefault();
    e.stopPropagation();
    e.stopImmediatePropagation();
    pushView("ticket-detail", button.getAttribute("data-ticket-detail-view"), "Ticket");
  }, true);

  /* Ticket popup and complete-view tabs. */
  root.addEventListener("click", function (e) {
    var tab = e.target.closest("[data-ticket-tab]");
    if (!tab || !root.contains(tab)) return;

    e.preventDefault();
    e.stopPropagation();

    var host = tab.closest("[data-m-body], [data-f-body]") || root;
    var key = tab.getAttribute("data-ticket-tab");

    host.querySelectorAll("[data-ticket-tab]").forEach(function (button) {
      var active = button === tab;
      button.classList.toggle("active", active);
      button.setAttribute("aria-selected", active ? "true" : "false");
    });

    host.querySelectorAll("[data-ticket-panel]").forEach(function (panel) {
      panel.hidden = panel.getAttribute("data-ticket-panel") !== key;
    });
  });

  /*
   * Use the dashboard root instead of binding each current .grid separately.
   * This keeps every popup clickable even when a grid is re-rendered, moved,
   * or replaced by Frappe after the script has started.
   */
  /* Capture-phase tile handler: ERPNext wrappers or other scripts cannot
     swallow the card click before the dashboard receives it. */
  root.addEventListener("click", function (e) {
    var target = e.target && e.target.closest ? e.target : null;
    var tile = target ? target.closest("[data-tile]") : null;
    if (!tile || !root.contains(tile)) return;
    e.preventDefault();
    e.stopPropagation();
    var tileKey = tile.getAttribute("data-tile");

    if (tileKey === "clientinfo") {
      openClientInfoDashboardTab();
      return;
    }

    if (tileKey === "ticket" || tileKey === "ticket-detail") tileKey = "tickets";
    if (tileKey === "task" || tileKey === "task-detail") tileKey = "tasks";
    openModal(tileKey);
  }, true);

  root.addEventListener("keydown", function (e) {
    if (e.key !== "Enter" && e.key !== " ") return;
    var target = e.target && e.target.closest ? e.target : null;
    var tile = target ? target.closest("[data-tile]") : null;
    if (!tile || !root.contains(tile)) return;
    e.preventDefault();
    e.stopPropagation();
    var tileKey = tile.getAttribute("data-tile");

    if (tileKey === "clientinfo") {
      openClientInfoDashboardTab();
      return;
    }

    if (tileKey === "ticket" || tileKey === "ticket-detail") tileKey = "tickets";
    if (tileKey === "task" || tileKey === "task-detail") tileKey = "tasks";
    openModal(tileKey);
  }, true);

  /* Console diagnostic: LIFE_COO_OPEN("sales") */
  window.LIFE_COO_OPEN = function (tileKey) {
    openModal(String(tileKey || "sales"));
  };

  safeOn("[data-close]", "click", closeModal);
  safeOn("[data-back]", "click", popView);

  /* drill-down: any row with data-drill opens the next level */
  var DRILL_LABEL = {
    "branch-detail": function (k) { return k; },
    "invoice": function (k) { return "Invoice " + k; },
    "agent-detail": function (k) { return k; },
    "source-detail": function (k) { return k; },
    "category-detail": function (k) { return k; },
    "grievance-detail": function (k) { return "Ticket"; },
    "approval-detail": function (k) { return "Request"; },
    "appointment-detail": function (k) { return "Appointment"; },
    "task-detail": function (k) { return "Task"; },
    "hr-detail": function (k) { return k + " team"; },
    "asset-cat-detail": function (k) { return k; },
    "dept-detail": function (k) { return k; },
    "ticket-detail": function (k) { return "Ticket"; },
    "mop-detail": function (k) { return k; },
    "po-detail": function (k) { return "Order " + k; },
    "c2c-detail": function (k) { return "C2C transfer"; },
    "b2b-detail": function (k) { return "B2B transfer"; },
    "p2p-detail": function (k) { return "P2P transfer"; }
  };
  function drillFrom(el) {
    var kind = el.getAttribute("data-drill");
    var key = el.getAttribute("data-key");
    if (!kind) return;
    var lab = DRILL_LABEL[kind] ? DRILL_LABEL[kind](key) : key;
    pushView(kind, key, lab);
  }
  root.addEventListener("click", function (e) {
    if (e.target.closest("a,button,input,select,textarea")) return;
    var recordRow = e.target.closest(
      "tr[data-open-doctype][data-open-name]"
    );
    if (!recordRow) return;
    e.preventDefault();
    openDeskDocument(
      recordRow.getAttribute("data-open-doctype"),
      recordRow.getAttribute("data-open-name")
    );
  });

  root.addEventListener("keydown", function (e) {
    if (e.key !== "Enter" && e.key !== " ") return;
    var recordRow = e.target.closest(
      "tr[data-open-doctype][data-open-name]"
    );
    if (!recordRow) return;
    e.preventDefault();
    openDeskDocument(
      recordRow.getAttribute("data-open-doctype"),
      recordRow.getAttribute("data-open-name")
    );
  });

  safeOn("[data-m-body]", "click", function (e) {
    if (e.target.closest("a")) return; // let portal links through
    var tr = e.target.closest("tr[data-drill]");
    if (tr) drillFrom(tr);
  });
  safeOn("[data-m-body]", "keydown", function (e) {
    if (e.key !== "Enter" && e.key !== " ") return;
    var tr = e.target.closest("tr[data-drill]");
    if (tr) { e.preventDefault(); drillFrom(tr); }
  });

  /* Complete View rows for Task Management and Tickets open the dashboard
     detail popup instead of navigating to the ToDo / Issue DocType. */
  safeOn("[data-f-body]", "click", function (e) {
    if (e.target.closest("a,button,input,select,textarea")) return;
    var tr = e.target.closest("tr[data-drill]");
    if (!tr) return;

    var kind = tr.getAttribute("data-drill");
    if (kind !== "task-detail" && kind !== "ticket-detail") return;

    e.preventDefault();
    var key = tr.getAttribute("data-key");
    var rootTile = kind === "task-detail" ? "tasks" : "tickets";

    closeFull();
    nav = [{ t: rootTile, arg: null, label: TITLES[rootTile] || rootTile }];
    pushView(kind, key, DRILL_LABEL[kind] ? DRILL_LABEL[kind](key) : key);
    showPopupOverlayAgain();
  });

  safeOn("[data-f-body]", "keydown", function (e) {
    if (e.key !== "Enter" && e.key !== " ") return;
    var tr = e.target.closest("tr[data-drill]");
    if (!tr) return;

    var kind = tr.getAttribute("data-drill");
    if (kind !== "task-detail" && kind !== "ticket-detail") return;

    e.preventDefault();
    var key = tr.getAttribute("data-key");
    var rootTile = kind === "task-detail" ? "tasks" : "tickets";

    closeFull();
    nav = [{ t: rootTile, arg: null, label: TITLES[rootTile] || rootTile }];
    pushView(kind, key, DRILL_LABEL[kind] ? DRILL_LABEL[kind](key) : key);
    showPopupOverlayAgain();
  });
  safeOn("[data-ovl]", "click", function (e) {
    if (e.target === $("[data-ovl]")) closeModal();
  });
  root.addEventListener("keydown", function (e) {
    if (e.key !== "Escape") return;
    if ($("[data-full]").classList.contains("on")) {
      closeFull();
      showPopupOverlayAgain();
      return;
    }
    if ($("[data-ovl]").classList.contains("on")) popView();
  });
  safeOn("[data-go]", "click", function () {
    var r0 = nav[0];
    if (r0) openFull(r0.t);
  });
  safeOn("[data-full-back]", "click", function () {
    closeFull();
    showPopupOverlayAgain();
  });
  safeOn("[data-full-close]", "click", function () { closeFull(); closeModal(); });

  safeOn("[data-refresh]", "click", function () {
    loadAll({ preserveCurrentCards: true }).then(function () {
      if (nav.length) paint();
      if (activeFull) refreshFull(activeFull);
      toast("Refreshed " + rangeText());
    });
  });
  safeOn("[data-branch-sel]", "change", function (e) {
    state.branch = e.target.value;
    state.emp = "ALL";
    fillEmpSel();
    render();
    if (nav.length) paint();
    if (activeFull) refreshFull(activeFull);
    if (state.branch === "ALL" && state.emp === "ALL") saveDashboardSnapshot();
    toast(state.branch === "ALL" ? "Showing all 11 branches" : "Filtered: " + state.branch);
  });
  safeOn("[data-emp-sel]", "change", function (e) {
    state.emp = e.target.value;
    render();
    if (nav.length) paint();
    if (activeFull) refreshFull(activeFull);
    toast(state.emp === "ALL" ? "All employees" : "Filtered: " + state.emp);
  });

  /*
    SALES QUICK RANGE CORRECT COLLECTIONS V17
    --------------------------------
    Handle the Sales Summary / Branch Ranking Apply button at document
    capture level. The document receives the click before the dashboard root,
    so no older generic handler can change only the date labels while leaving
    the business-cycle totals on screen.

    This handler calls the normal loadSalesPageRange() function. Therefore the
    exact submitted Sales Invoice rows are stored in state.pageData and are
    used by KPIs, branch table, drill-downs and Complete View.
  */
  document.addEventListener("click", function (e) {
    var btn =
      e.target && e.target.closest
        ? e.target.closest("[data-range-apply]")
        : null;

    if (!btn || !root.contains(btn)) return;

    var host = btn.closest("[data-range-panel]");
    if (!host) return;

    var rawTileKey = host.getAttribute("data-range-tile") || "";
    var tileKey = canonicalSalesRangeTile(rawTileKey);

    if (!tileKey) {
      var modalTitle = String(
        ((root.querySelector("[data-m-title]") || {}).textContent || "")
      ).toLowerCase().replace(/[\s_-]+/g, "");

      if (modalTitle.indexOf("salessummary") >= 0) tileKey = "sales";
      else if (modalTitle.indexOf("branchranking") >= 0) tileKey = "branches";
    }

    if (!tileKey) return;

    e.preventDefault();
    e.stopPropagation();
    e.stopImmediatePropagation();

    var fromEl = host.querySelector("[data-range-from]");
    var toEl = host.querySelector("[data-range-to]");
    var presetEl = host.querySelector("[data-range-preset]");
    var branchEl = host.querySelector("[data-popup-branch]");

    var fromDate = fromEl ? fromEl.value : "";
    var toDate = toEl ? toEl.value : "";
    var selectedBranch = branchEl ? branchEl.value : "ALL";

    var help = host.querySelector(".range-help");
    if (help) {
      help.textContent =
        "Loading submitted Sales Invoices and Receive Payment Entries for Posting Date " +
        formatBusinessDate(fromDate) + " to " +
        formatBusinessDate(toDate) + "…";
    }


    loadSalesPageRange(
      tileKey,
      fromDate,
      toDate,
      presetEl ? presetEl.value : "custom",
      selectedBranch,
      btn
    );
  }, true);

  /* ---------- init ---------- */
  var sel = $("[data-branch-sel]");
  if (sel) {
    BRANCHES.forEach(function (b) {
      var o = document.createElement("option");
      o.value = b; o.textContent = b;
      sel.appendChild(o);
    });
  }
  syncRangeControls();

  /*
   * Final initial-render safety scan after all standard dropdown options
   * have been populated.
   */
  removeHeadOfficeFromSelects(root);

  function clock() {
    var d = new Date();
    $("[data-clk-t]").textContent = ("0" + d.getHours()).slice(-2) + ":" + ("0" + d.getMinutes()).slice(-2);
    $("[data-clk-d]").textContent = d.toLocaleDateString("en-IN", { day: "2-digit", month: "short" });
  }
  clock();
  var ci = setInterval(clock, 30000);
  var ri = setInterval(function () {
    if (document.visibilityState && document.visibilityState !== "visible") return;
    loadAll({ preserveCurrentCards: true }).then(function () {
      if (nav.length) paint();
      if (activeFull) refreshFull(activeFull);
    });
  }, 300000); // 5 min auto-refresh, only while this tab is visible

  var restoredDashboardSnapshot = restoreDashboardSnapshot();
  loadAll({ preserveCurrentCards: restoredDashboardSnapshot });
  }
})();
